const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toISOString().slice(0,10), uuid=()=>crypto.randomUUID();
const amount=v=>Math.round((Number(v)+Number.EPSILON)*100);
const round=(n,r)=>Math.round(n*Number(r));
let state=null,queue=[],token=sessionStorage.getItem('token'),route=location.hash.slice(1)||'dashboard',currency=localStorage.getItem('currency')||'USD',period='week',from='',to=today(),search='',subtab='',cart=[],payments=[],syncing=false,db,lastSync='',posCurrency='USD';
let selectedInvoiceId=null;const initialInvoiceRoute=route.match(/^sales\/invoice\/([A-Za-z0-9-]+)$/);if(initialInvoiceRoute){selectedInvoiceId=initialInvoiceRoute[1];route='sales';subtab='detail'}
let draftDiscount=0;const device=localStorage.getItem('device')||'PHARMACY-01';
const ready=new Promise((resolve,reject)=>{const r=indexedDB.open('medledger-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('store');r.onsuccess=()=>{db=r.result;resolve()};r.onerror=()=>reject(r.error)});
let vaultKey=null,authGeneration=0,lockingSession=false,loginNotice='',lastBeatSent=0,lastBeatInput=0;
const idleSession=createIdleSession({hasSession:()=>!!state&&!!token,onTimeout:()=>automaticLogout('Signed out after 5 minutes of inactivity.'),onActivity:()=>activityHeartbeat()});
function beginSession(resume=false){authGeneration++;loginNotice='';idleSession.start(resume);lastBeatSent=0;lastBeatInput=0;if(state)activityHeartbeat()}
async function activityHeartbeat(){
 if(!state||!token||!navigator.onLine||lockingSession||idleSession.expired)return;
 if(Date.now()-lastBeatSent<30000||idleSession.lastActivity<=lastBeatInput)return;
 const activity=idleSession.lastActivity;lastBeatSent=Date.now();
 try{await api('activity',{idle_ms:Math.max(0,Date.now()-activity)});lastBeatInput=activity}catch(error){if(error.needsLogin&&state)await automaticLogout('Your session expired. Sign in again.')}
}
async function automaticLogout(message){
 if(lockingSession)return;
 lockingSession=true;authGeneration++;idleSession.stop();
 const oldToken=token,cachedState=state;
 for(const event of queue)if(event.status==='syncing')event.status='pending';
 token=null;state=null;cart=[];payments=[];draftDiscount=0;loginNotice=message;
 sessionStorage.clear();localStorage.removeItem('auth-mode');
 if($('#modal').open)$('#modal').close();$('#modal').innerHTML='';document.querySelector('#confirm-dialog')?.close();render();
 if(oldToken&&navigator.onLine)fetch('/api/logout',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json',...(oldToken!=='cookie-auth'?{Authorization:'Bearer '+oldToken}:{})},body:'{}',signal:AbortSignal.timeout(3000)}).catch(()=>{});
 try{if(vaultKey){await put('queue',queue);if(cachedState)await put('state',cachedState)}}catch{}finally{vaultKey=null;queue=[];lastSync='';lockingSession=false;const button=$('#login-form button[type=submit]');if(button)button.disabled=false}
}

async function rawGet(key){await ready;return new Promise(res=>{const r=db.transaction('store').objectStore('store').get(key);r.onsuccess=()=>res(r.result)})}
async function rawPut(key,value){await ready;return new Promise((res,rej)=>{const t=db.transaction('store','readwrite');t.objectStore('store').put(value,key);t.oncomplete=res;t.onerror=()=>rej(t.error)})}
async function get(key){const data=await rawGet(key);if(!data)return null;if(!data.encrypted)return data;if(!vaultKey)throw Error('Unlock this device with your password');try{return JSON.parse(new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:new Uint8Array(data.iv)},vaultKey,new Uint8Array(data.bytes))))}catch{throw Error('Unable to unlock local records. Use the password that authorized this device.')}}
async function put(key,value){if(value===null)return rawPut(key,null);if(!vaultKey)throw Error('Local encryption key unavailable');const iv=crypto.getRandomValues(new Uint8Array(12));const bytes=await crypto.subtle.encrypt({name:'AES-GCM',iv},vaultKey,new TextEncoder().encode(JSON.stringify(value)));return rawPut(key,{encrypted:true,iv:[...iv],bytes:[...new Uint8Array(bytes)]})}
async function unlockVault(email,password){let meta=await rawGet('vault');if(meta&&meta.email!==email)throw Error('Sign out of the current device account before switching users.');if(!meta){meta={email,salt:[...crypto.getRandomValues(new Uint8Array(16))]};await rawPut('vault',meta)}const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);vaultKey=await crypto.subtle.deriveKey({name:'PBKDF2',salt:new Uint8Array(meta.salt),iterations:250000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},true,['encrypt','decrypt']);const saved=await rawGet('state');if(saved)await get('state');sessionStorage.setItem('vault-key',JSON.stringify([...new Uint8Array(await crypto.subtle.exportKey('raw',vaultKey))]));}
function fmt(n,c=currency){return new Intl.NumberFormat('en-US',{style:'currency',currency:c==='ZiG'?'ZWG':c,minimumFractionDigits:2}).format((n||0)/100).replace('ZWG','ZiG')}
function rate(c){return [...state.rates].filter(r=>r.currency===c&&r.effective<=today()).sort((a,b)=>b.effective.localeCompare(a.effective)||b.created.localeCompare(a.created))[0]}
function display(n){return fmt(Math.round(n/Number(rate(currency)?.rate||1)))}
const fullDate=d=>new Date(d).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const shortDate=d=>new Date(d).toLocaleDateString('en-GB',{day:'2-digit',month:'short'});
function dates(p){to=today();let d=new Date();if(p==='today')from=to;else if(p==='week'){d.setDate(d.getDate()-6);from=d.toISOString().slice(0,10)}else if(p==='month')from=to.slice(0,8)+'01';else from='2000-01-01'}dates(period);
const inPeriod=d=>d.slice(0,10)>=from&&d.slice(0,10)<=to;
const financial=()=>['super_admin','admin','manager','accountant'].includes(state.user.role);
const stockQty=p=>state.batches.filter(b=>b.product_id===p&&b.status==='available'&&b.expiry>=today()).reduce((a,b)=>a+b.quantity,0);
const product=id=>state.products.find(p=>p.id===id);
const customer=id=>state.customers.find(c=>c.id===id)?.name||'Walk-in customer';
const badge=(s,type='')=>`<span class="badge ${type}"><span class="dot"></span>${esc(s)}</span>`;
function toast(text,error=false){$('#toast').innerHTML=icon(error?'alert':'check')+'<span>'+esc(text)+'</span>';$('#toast').style.background=error?'#b91c1c':'#15803d';$('#toast').style.display='flex';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5500)}
async function api(path,body){const generation=authGeneration,authenticated=!!token,bearer=token&&token!=='cookie-auth'&&!state?.production;const res=await fetch('/api/'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:{'Content-Type':'application/json',...(bearer?{Authorization:'Bearer '+token}:{})},body:body?JSON.stringify(body):undefined});const data=await res.json();if(authenticated&&generation!==authGeneration){const error=new Error('Session ended. Sign in again to continue.');error.needsLogin=true;throw error}if(!res.ok){const error=new Error(data.error||'Request failed');error.status=res.status;error.needsLogin=res.status===401||((res.status===403)&&String(data.error).startsWith('Session'));throw error}return data}
function modal(title,body,wide=false){const m=$('#modal');m.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" data-close aria-label="Close">${icon('close')}</button></div><div class="modal-body">${body}</div>`;m.style.maxWidth=wide?'950px':'640px';m.querySelector('[data-close]').onclick=()=>m.close();if(!m.open)m.showModal()}
function input(name,label,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function select(name,label,options,value=''){return `<label>${label}<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}
function accountsOptions(){return state.accounts.map(a=>[a.id,`${a.name} · ${a.currency} (${a.balance===null?'balance restricted':fmt(a.balance,a.currency)})`])}
function form(title,fields,kind,transform=x=>x,notice=''){modal(title,`<form id="entry-form"><div class="form-grid">${fields}${notice?`<div class="form-note full">${notice}</div>`:''}</div><div class="error" id="form-error"></div><div class="form-actions">${({product:'products',stock:'batches',customer:'customers',expense:'expenses',asset:'assets'})[kind]?`<button type="button" data-form-csv="${({product:'products',stock:'batches',customer:'customers',expense:'expenses',asset:'assets'})[kind]}">${icon('upload')} Upload CSV</button>`:''}<button type="button" data-cancel>Cancel</button><button class="primary" type="submit">${icon('check')} Save ${esc(title.toLowerCase())}</button></div></form>`);if($('#entry-form [data-form-csv]'))$('#entry-form [data-form-csv]').onclick=e=>openImporter(e.currentTarget.dataset.formCsv);$('#entry-form [data-cancel]').onclick=()=>$('#modal').close();$('#entry-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter||e.target.querySelector('button.primary');b.disabled=true;try{let p=transform(Object.fromEntries(new FormData(e.target)));if(!await confirmOperation(kind,p))return;await submit(kind,p);$('#modal').close()}catch(err){if($('#form-error'))$('#form-error').textContent=err.message;else toast(err.message,true)}finally{b.disabled=false}}}
function ask(options){return confirmAction({...options,icon})}
async function confirmOperation(kind,p){
 if(kind==='refund')return ask({title:'Issue this credit note and refund?',message:'This reverses the complete sale and refunds its recorded payments. Returned stock will require inspection before resale.',confirmLabel:'Issue credit note'});
 if(kind==='dispose'){const asset=state.assets.find(a=>a.id===p.asset_id);return ask({title:'Do you really want to dispose of this asset?',message:(asset?.description||'This asset')+' will be marked disposed and its disposal will be posted to the accounts.',confirmLabel:'Dispose asset'})}
 if(kind==='adjust'){const batch=state.batches.find(b=>b.id===p.batch_id),loss=Number(p.counted)<Number(batch?.quantity);return ask({title:loss?'Confirm stock write-off?':'Confirm stock adjustment?',message:'Batch '+(batch?.number||p.batch_id)+': change recorded quantity from '+(batch?.quantity??'?')+' to '+p.counted+' units. Reason: '+p.reason,confirmLabel:loss?'Write off stock':'Apply adjustment',danger:loss})}
 if(kind==='inspect')return ask({title:p.decision==='reject'?'Reject and write off this return?':'Release this returned stock?',message:p.decision==='reject'?'The inspected quantity will be removed from stock and its loss recorded.':'The inspected goods will become available for resale, subject to expiry and authorization checks.',confirmLabel:p.decision==='reject'?'Reject return':'Release stock',danger:p.decision==='reject'});
 if(kind==='batch_status')return ask({title:'Change this batch to '+p.status+'?',message:'This changes whether the batch can be sold. Your reason will be retained in the stock history.',confirmLabel:'Change batch status',danger:p.status!=='available'});
 if(kind==='transfer')return ask({title:'Confirm account transfer?',message:'Transfer '+p.amount+' from '+(state.accounts.find(a=>a.id===p.account_id)?.name||p.account_id)+' and receive '+p.received+' in '+(state.accounts.find(a=>a.id===p.to_account)?.name||p.to_account)+'.',confirmLabel:'Confirm transfer',danger:false});
 if(kind==='till'&&p.action==='close')return ask({title:'Close and reconcile this till?',message:'The counted amount of '+p.counted+' will be compared with the expected balance. Any variance will be recorded.',confirmLabel:'Close till',danger:false});
 if(kind==='rate')return ask({title:'Approve this exchange rate?',message:'1 '+p.currency+' = '+p.rate+' USD, effective '+p.effective+'. Existing invoices retain their original rates.',confirmLabel:'Approve rate',danger:false});
 return true;
}
async function submit(kind,payload){
    const event={id:uuid(),kind,device,event_time:new Date().toISOString(),payload,offline:!navigator.onLine,data_epoch:state.settings.data_epoch||'legacy'};
    const offlineAllowed=['sale','receipt','expense','quote','draft'].includes(kind);
    if(!navigator.onLine){
        if(state.settings.policy.offlineEnabled===false)throw Error('Offline transactions are disabled for this production workspace. Reconnect before saving.');
        if(!offlineAllowed)throw Error('This operation requires a connection');
        if(device!==state.settings.policy.offlineDevice)throw Error('This terminal is not authorized for offline selling');
        if(Date.now()-Date.parse(state.server_time)>state.settings.policy.offlineHours*3600000)throw Error('Offline authorization expired. Reconnect and sign in.');
        validateOffline(event);
    }
    const queued={...event,status:'pending'};queue.push(queued);await put('queue',queue);
    if(navigator.onLine){
        let response;
        try{response=await api('events',event)}catch(e){
            if(e.needsLogin){queued.status='pending';queued.error=e.message;if(vaultKey)await put('queue',queue);if(state)await automaticLogout(e.message);throw e}if(!(e instanceof TypeError)){queued.status='abandoned';queued.error=e.message;await put('queue',queue);throw e}
            queued.error='Connection interrupted; original request retained for exactly-once retry.';await put('queue',queue);
            if(!offlineAllowed){render();throw Error('Connection interrupted. The original request is retained in the sync queue; review its result before submitting again.')}
        }
        if(response){
            queued.status='synced';state=response.state;lastSync=state.server_time;
            try{await put('queue',queue);await put('state',state);await put('lastSync',lastSync)}catch{toast('Transaction posted. Local cache update failed; reconnect before working offline.',true)}
            render();toast(response.result.message);return response.result;
        }
    }
    render();toast('Saved on this device. Pending synchronization.');return {id:event.id,offline:true};
}
function validateOffline(e){if(e.kind!=='sale')return;for(const item of e.payload.items){let p=product(item.product_id);let reserved=queue.filter(q=>!['abandoned','synced'].includes(q.status)&&q.kind==='sale').flatMap(q=>q.payload.items).filter(x=>x.product_id===p.id).reduce((a,x)=>a+Number(x.quantity),0);if(stockQty(p.id)-reserved<Number(item.quantity))throw Error('Insufficient allocated stock for '+p.name);if(p.rx&&!['super_admin','admin','manager','pharmacist'].includes(state.user.role))throw Error('Pharmacist authorization required');if(p.rx&&!e.payload.prescription)throw Error('Prescription reference required')};const r=rate(e.payload.currency);if(e.payload.currency!=='USD'&&(Date.now()-Date.parse(r.effective))/86400000>state.settings.policy.rateAgeDays)throw Error('Approved exchange rate is stale');}
async function sync(){
 if(syncing||!token||!navigator.onLine)return;syncing=true;
 try{
  for(const q of queue.filter(q=>q.status==='pending'||q.status==='failed')){
   q.status='syncing';await put('queue',queue);const wire={...q};delete wire.status;delete wire.error;
   try{const r=await api('events',wire);state=r.state;q.status='synced';lastSync=state.server_time;await put('state',state);await put('lastSync',lastSync)}
   catch(e){if(e.needsLogin){q.status='pending';q.error=e.message;if(vaultKey)await put('queue',queue);if(state)await automaticLogout(e.message);return}q.status=e instanceof TypeError?'failed':'conflict';q.error=e.message}
   await put('queue',queue);
  }
  if(state&&!queue.some(q=>q.status==='conflict')){state=await api('state');lastSync=state.server_time;await put('state',state);await put('lastSync',lastSync)}
 }catch(e){if(e.needsLogin&&state)await automaticLogout(e.message);else if(!(e instanceof TypeError))toast(e.message,true)}
 finally{syncing=false;if(state)render()}
}

function pending(){return queue.filter(q=>!['synced','abandoned'].includes(q.status)).length}
function navTo(r,tab=''){route=r;subtab=tab;search='';location.hash=r;render()}
function sidebarMenu(){
    const item=(r,tab,label,i)=>`<button data-route="${r}" data-tab="${tab}" class="sidebar-link ${route===r&&(subtab===tab||(r==='sales'&&tab==='invoices'&&subtab==='detail'))?'current':''}" ${route===r&&(subtab===tab||(r==='sales'&&tab==='invoices'&&subtab==='detail'))?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`;
    const group=(id,label,i,items,active)=>{const saved=sessionStorage.getItem('nav-group-'+id);const open=saved===null?active:saved==='open';return `<details class="sidebar-group" data-nav-group="${id}" ${open?'open':''}><summary>${icon(i)}<span>${label}</span>${icon('chevron','group-chevron')}</summary><div class="sidebar-children">${items}</div></details>`};
    const initials=state.user.name.split(' ').map(x=>x[0]).slice(0,2).join('');
    return `<aside class="reference-sidebar"><div class="brand company-brand"><span class="brand-image"><img src="/brand-logo-current.png" alt="Thachi Investments logo"><img class="brand-pill-accent" src="/brand-logo-current.png" alt="" aria-hidden="true"></span></div><nav class="reference-nav" aria-label="Main navigation">${item('dashboard','','Dashboard','grid')}${group('sales','Sales','banknote',item('sales','','All transactions','sales')+item('sales','pos','Point of sale','sales')+item('sales','invoices','Invoices','file')+item('sales','credits','Credit notes','receipt')+item('sales','quotes','Quotes','quote')+item('sales','drafts','Saved drafts','draft')+item('sales','receivables','Receivables','receipt'),route==='sales')}${group('finance','Finance','bank',item('cash','','Cash Flow','cash')+item('assets','','Assets','asset')+item('expenses','','Expenses','expense')+item('reports','','Reports','chart'),['cash','assets','expenses','reports'].includes(route))}${group('catalog','Catalog','tag',item('inventory','','Product catalogue','pill')+item('sales','customers','Customers','user'),route==='inventory'&&subtab===''||route==='sales'&&subtab==='customers')}${group('inventory','Inventory','archive',item('inventory','batches','Batches','box')+item('inventory','low','Low stock','alert')+item('inventory','expiry','Expiry alerts','clock')+item('inventory','ledger','Stock ledger','file'),route==='inventory'&&subtab!=='')}${group('security','Security','users',item('profile','','Profile','user')+item('settings','','Settings','settings'),['profile','settings'].includes(route))}</nav><div class="reference-account"><div class="account-identity"><span class="account-avatar">${esc(initials)}</span><div><strong>${esc(state.user.name)}</strong><span title="${esc(state.user.email)}">${esc(state.user.email)}</span></div></div><div class="account-actions"><button data-route="profile">${icon('user')}Profile</button><button data-action="logout" class="account-signout">${icon('logout')}Sign Out</button></div></div></aside>`;
}
function shell(){const nav=[['dashboard','grid','Dashboard'],['sales','sales','Sales'],['cash','cash','Cash Flow'],['assets','asset','Assets'],['expenses','expense','Expenses'],['inventory','box','Inventory'],['profile','user','Profile'],['settings','settings','Settings']];const name=nav.find(n=>n[0]===route)?.[2]||'Reports';return `${sidebarMenu()}<div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu icon-button" aria-label="Open menu" id="menu">${icon('menu')}</button>Workspace ${icon('chevron')} <strong>${name}</strong></div><div class="top-actions"><span class="online" style="color:${navigator.onLine?'#15803d':'#b45309'}"><span class="dot"></span>${navigator.onLine?'Online':'Offline'}</span><select id="currency" class="currency" aria-label="Reporting currency">${['USD','ZAR','ZiG'].map(c=>`<option ${c===currency?'selected':''}>${c}</option>`).join('')}</select><span class="divider"></span><button class="icon-button" id="notifications" aria-label="Notifications">${icon('bell')}${pending()?`<span class="badge amber">${pending()}</span>`:''}</button><span class="divider"></span><span class="avatar">${esc(state.user.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div class="profile-name"><strong style="font-size:11px">${esc(state.user.name)}</strong><small class="muted" style="display:block;font-size:10px;margin-top:3px">${esc(state.user.role==='super_admin'?'Super Administrator':state.user.role==='admin'?'Administrator':state.user.role)}</small></div></div></header><main class="content" id="main"></main></div>`}
function head(title,description,buttons=''){return `<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div><div class="head-actions">${buttons}</div></div>`}
function periodFilter(){return `<div class="period-row"><div class="tabs">${[['today','Today'],['week','This week'],['month','This month'],['all','All time']].map(([p,n])=>`<button data-period="${p}" class="${period===p?'selected':''}">${n}</button>`).join('')}</div><div class="date-filter">${icon('calendar')}<input type="date" id="from" aria-label="Start date" value="${from}"><span>—</span><input type="date" id="to" aria-label="End date" value="${to}"></div></div>`}
function foot(){return `<footer><span>© ${new Date().getFullYear()} Thachi Investiments. Every detail accounted for.</span><button class="text-button sync-footer" data-action="sync">${icon('sync')} ${pending()} pending · ${lastSync?'Synced '+new Date(lastSync).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):'Not synced'}</button></footer>`}
function stat(label,value,i,color,sub){return `<div class="card stat"><div class="stat-label">${label}<span class="stat-icon ${color}">${icon(i)}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${sub}</div></div>`}
function ledgerTotal(account,side='debit'){return state.journals.filter(j=>inPeriod(j.date)&&(typeof account==='function'?account(j.account):j.account===account)).reduce((s,j)=>s+(side==='credit'?j.credit-j.debit:j.debit-j.credit),0)}
function metrics(){const sales=state.documents.filter(d=>d.kind==='sale'&&inPeriod(d.date));const net=ledgerTotal('sales','credit');const cogs=ledgerTotal('cogs');const expenses=ledgerTotal(a=>a.startsWith('expense:'));return {sales,net,cogs,expenses,profit:net-cogs-expenses-ledgerTotal('depreciation')-ledgerTotal('stock_loss')+ledgerTotal('fx_gain_loss','credit')+ledgerTotal('asset_gain_loss','credit'),cashIn:state.payments.filter(p=>inPeriod(p.date)&&p.direction==='in'&&!p.reference?.startsWith('opening')).reduce((s,p)=>s+p.base_amount,0),cashOut:state.payments.filter(p=>inPeriod(p.date)&&p.direction==='out').reduce((s,p)=>s+p.base_amount,0)}}
function trendChart(){let days=[];let start=new Date(from);let end=new Date(to);let span=Math.max(1,Math.round((end-start)/86400000)+1);if(span>35){start=new Date(end);start.setDate(start.getDate()-29);span=30}for(let i=0;i<span;i++){let d=new Date(start);d.setDate(d.getDate()+i);let key=d.toISOString().slice(0,10);let entries=state.journals.filter(j=>j.date.startsWith(key));let rev=entries.filter(j=>j.account==='sales').reduce((s,j)=>s+j.credit-j.debit,0),cost=entries.filter(j=>j.account==='cogs').reduce((s,j)=>s+j.debit-j.credit,0);days.push({d:key,s:rev,p:rev-cost})}const max=Math.max(100,...days.map(d=>d.s));let w=640,h=180,left=46,plotW=570;const y=v=>h-(v/max)*145;const points=(key)=>days.map((d,i)=>`${left+(i*plotW/Math.max(1,days.length-1))},${y(d[key])}`).join(' ');return `<svg class="chart" viewBox="0 0 650 220" role="img" aria-label="Daily sales and gross profit"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#3b82f6" stop-opacity=".17"/><stop offset="100%" stop-color="#3b82f6" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>{let v=max*i/3;return `<line x1="45" y1="${y(v)}" x2="625" y2="${y(v)}"/><text x="0" y="${y(v)+4}">${Math.round(v/100)}</text>`}).join('')}<polygon points="${left},${h} ${points('s')} ${left+plotW},${h}" fill="url(#area)"/><polyline points="${points('p')}" fill="none" stroke="#60b8af" stroke-width="2"/><polyline points="${points('s')}" fill="none" stroke="#2563eb" stroke-width="2.5" stroke-linejoin="round"/>${days.filter((d,i)=>i%Math.max(1,Math.floor(days.length/7))===0).map(d=>{let i=days.indexOf(d);return `<text x="${left+(i*plotW/Math.max(1,days.length-1))}" y="208" text-anchor="middle">${shortDate(d.d)}</text>`}).join('')}</svg>`}
function expenseDonut(){let groups={};for(let d of state.documents.filter(d=>d.kind==='expense'&&inPeriod(d.date)))groups[d.category||'Other']=(groups[d.category||'Other']||0)+d.base_total;let total=Object.values(groups).reduce((a,b)=>a+b,0);let palette=['#2563eb','#5b9cf4','#14b8a6','#a7d5eb','#cbd5e1'];let pos=0;let stops=Object.entries(groups).map(([k,v],i)=>{let start=pos;pos+=total?v/total*100:0;return `${palette[i%5]} ${start}% ${pos}%`});return `<div class="expense-visual"><div class="donut" style="background:conic-gradient(${stops.length?stops.join(','):'#e2e8f0 0% 100%'})"><div class="donut-label"><small>Total expenses</small><strong>${display(total)}</strong></div></div></div><div class="expense-legend">${Object.entries(groups).map(([k,v],i)=>`<div><span class="dot" style="color:${palette[i%5]}"></span>${esc(k)}<b>${Math.round(v/total*100)}%</b></div>`).join('')||'<span>No expenses this period</span>'}</div>`}
function documentDeleteAction(d){const deletable=['quote','draft'].includes(d.kind),linked=state.documents.some(child=>child.parent_id===d.id);if(deletable&&!linked)return `<button class="invoice-eye-action danger" data-delete-doc="${d.id}" aria-label="Delete ${d.kind} ${esc(d.number)}" title="Delete ${d.kind}">${icon('trash')}</button>`;if(d.kind==='sale'&&d.status!=='reversed'&&['super_admin','admin','manager'].includes(state.user.role))return `<button class="invoice-eye-action danger" data-void-sale="${d.id}" aria-label="Void invoice ${esc(d.number)}" title="Void invoice and issue full credit note">${icon('trash')}</button>`;const reason=linked?'This document has linked records and cannot be deleted.':d.kind==='sale'?'Posted sales are preserved. An administrator or manager can void with a full credit note.':'Posted financial records are retained.';return `<button class="invoice-eye-action danger" disabled aria-label="Delete unavailable for ${esc(d.number)}" title="${reason}">${icon('trash')}</button>`}
function salesTable(docs,limit=100){return `<div class="table-scroll"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Date</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody>${docs.slice(0,limit).map(d=>`<tr><td><strong>${esc(d.number)}</strong></td><td>${esc(customer(d.customer_id))}</td><td>${shortDate(d.date)}</td><td><strong>${fmt(d.total,d.currency)}</strong></td><td>${badge(d.status==='reversed'?'Reversed':d.kind==='refund'?'Credit note':d.kind==='quote'?'Quotation':d.kind==='draft'?'Draft':d.paid>=d.total?'Paid':d.paid?'Partial':'Unpaid',d.status==='reversed'?'red':d.paid>=d.total?'':'amber')}</td><td><button class="invoice-eye-action" data-doc="${d.id}" data-invoice-view="${d.id}" aria-label="View invoice ${esc(d.number)}" title="View document">${icon('eye')}</button> ${documentDeleteAction(d)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No transactions in this period</td></tr>'}</tbody></table></div>`}
function topProducts(){let counts={};for(let d of state.documents.filter(d=>d.kind==='sale'&&d.status!=='reversed'&&inPeriod(d.date))){for(let item of d.payload.items||[]){counts[item.product_id]=(counts[item.product_id]||0)+Number(item.quantity)}}return Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,4)}
function dashboard(){const m=metrics();const low=state.products.filter(p=>stockQty(p.id)>0&&stockQty(p.id)<=p.reorder).length;const out=state.products.filter(p=>!stockQty(p.id)).length;const exp=state.batches.filter(b=>b.quantity>0&&b.expiry>=today()&&b.expiry<=new Date(Date.now()+state.settings.policy.expiryDays*86400000).toISOString().slice(0,10)).length;const receivables=state.documents.filter(d=>d.kind==='sale'&&d.status!=='reversed').reduce((a,d)=>a+round(d.total-d.paid,d.rate),0);const tops=topProducts();return head('Business overview',`Here’s how your pharmacy is performing. Let’s make today count.`,`<button data-action="reports">${icon('down')} Export report</button><button class="primary" data-action="pos">${icon('plus')} New sale</button>`)+periodFilter()+`<div class="stats">${stat('Net sales',display(m.net),'sales','',`<span class="trend">${m.sales.length} sales</span> excluding sales tax`)}${stat('Gross profit',display(m.net-m.cogs),'trend','green',`<span class="trend">${m.net?Math.round((m.net-m.cogs)/m.net*100):0}% margin</span> after cost of goods`)}${stat('Operating expenses',display(m.expenses),'expense','amber','Posted operating costs this period')}${stat('Net profit',display(m.profit),'profit','teal','Accrual basis · separate from cash')}</div><div class="dashboard-grid"><section class="card"><div class="card-head"><div><h2>Sales performance</h2><p>Revenue and gross profit over time · USD</p></div><div class="legend"><span><i></i>Net sales</span><span><i class="light"></i>Gross profit</span></div></div><div class="chart-wrap">${trendChart()}</div><div class="chart-summary"><span>Cost of goods sold <strong>${display(m.cogs)}</strong></span><span>Cash received <strong>${display(m.cashIn)}</strong></span></div></section><section class="card"><div class="card-head"><div><h2>Expense breakdown</h2><p>Where your operating costs go</p></div><button class="icon-button" data-route="expenses" aria-label="View expenses">${icon('chevron')}</button></div>${expenseDonut()}</section></div><div class="alerts"><button class="alert" data-route="inventory" data-tab="low"><span class="alert-icon">${icon('box')}</span><div><strong>${low} products running low</strong><small>Keep your shelves ready for every patient</small></div><span class="arrow">${icon('chevron')}</span></button><button class="alert red" data-route="inventory" data-tab="expiry"><span class="alert-icon">${icon('clock')}</span><div><strong>${exp} batches expiring soon</strong><small>Within ${state.settings.policy.expiryDays} days · ${out} products out of stock</small></div><span class="arrow">${icon('chevron')}</span></button><button class="alert blue" data-route="sales" data-tab="receivables"><span class="alert-icon">${icon('file')}</span><div><strong>${display(receivables)} outstanding</strong><small>Customer balances awaiting payment</small></div><span class="arrow">${icon('chevron')}</span></button></div><div class="dashboard-grid"><section class="card"><div class="table-title"><h2>Recent transactions</h2><button class="text-button" data-route="sales">View all ${icon('arrow')}</button></div>${salesTable([...state.documents].filter(d=>d.kind==='sale'&&inPeriod(d.date)).sort((a,b)=>b.date.localeCompare(a.date)),5)}</section><section class="card"><div class="table-title"><h2>Top-selling products</h2><button class="text-button" data-route="inventory">View all</button></div><div class="table-scroll"><table><thead><tr><th>Product</th><th>Units sold</th></tr></thead><tbody>${tops.map(([id,q],i)=>`<tr><td><div class="product-cell"><span class="product-icon">${icon('pill')}</span><div><strong>${esc(product(id)?.name)}</strong><small>${esc(product(id)?.strength)} · ${esc(product(id)?.form)}</small></div></div></td><td><strong>${q}</strong><div class="progress"><i style="width:${q/tops[0][1]*100}%"></i></div></td></tr>`).join('')||'<tr><td colspan="2" class="empty">No sales yet</td></tr>'}</tbody></table></div></section></div>`+foot()}
function tabButtons(items){return `<div class="pill-nav">${items.map(([v,n])=>`<button data-tab="${v}" class="${subtab===v?'selected':''}">${n}</button>`).join('')}</div>`}
function salesPage(){if(subtab==='detail')return renderInvoiceDetails({id:selectedInvoiceId,state,icon,money:fmt,badge})+foot();if(subtab==='pos')return pos();let docs=state.documents.filter(d=>['sale','quote','draft','refund'].includes(d.kind)&&inPeriod(d.date));if(subtab==='receivables')docs=docs.filter(d=>d.kind==='sale'&&d.status!=='reversed'&&d.total>d.paid);if(subtab==='invoices')docs=docs.filter(d=>d.kind==='sale');if(subtab==='credits')docs=docs.filter(d=>d.kind==='refund');if(subtab==='quotes')docs=docs.filter(d=>d.kind==='quote');if(subtab==='drafts')docs=docs.filter(d=>d.kind==='draft');docs=docs.filter(d=>(d.number+' '+customer(d.customer_id)).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));return head('Sales & billing','Every sale, payment and customer balance in one place.',`${csvImportButton('customers',icon)}<button data-action="customer">${icon('user')} Add customer</button><button class="primary" data-action="pos">${icon('plus')} New sale</button>`)+tabButtons([['','All transactions'],['invoices','Invoices'],['credits','Credit notes'],['receivables','Receivables'],['quotes','Quotations'],['drafts','Saved drafts'],['customers','Customers']])+(subtab==='customers'?customersPage():periodFilter()+`<section class="card"><div class="toolbar"><div class="search">${icon('search')}<input id="search" placeholder="Search invoice or customer…" value="${esc(search)}"></div><button data-action="export-sales">${icon('down')} Export CSV</button></div>${salesTable(docs)}</section>`)+foot()}
function customersPage(){return `<section class="card"><div class="table-scroll"><table><thead><tr><th>Customer</th><th>Contact</th><th>Outstanding</th><th>Statement</th></tr></thead><tbody>${state.customers.filter(c=>c.id!=='walkin').map(c=>{let due=state.documents.filter(d=>d.customer_id===c.id&&d.kind==='sale'&&d.status!=='reversed').reduce((s,d)=>s+round(d.total-d.paid,d.rate),0);return `<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.email)}<small>${esc(c.phone)}</small></td><td>${display(due)}</td><td><button class="text-button" data-statement="${c.id}">View statement</button></td></tr>`}).join('')}</tbody></table></div></section>`}
function pos(){let r=Number(rate(posCurrency)?.rate||1),subtotal=cart.reduce((s,i)=>s+Math.round(product(i.product_id).price/r)*i.quantity,0),discount=amount(draftDiscount),tax=round(subtotal-discount,Number(state.settings.tax)/100),total=subtotal-discount+tax;let paid=payments.reduce((s,p)=>s+Math.round(amount(p.amount)*Number(rate(state.accounts.find(a=>a.id===p.account_id).currency)?.rate)/r),0);return head('New sale','Search a product or scan a barcode. Stock is allocated by first expiry.',`<button data-route="sales">${icon('close')} Close sale</button>`)+`<div class="pos-layout"><section class="card"><div class="toolbar"><div class="search">${icon('search')}<input id="product-search" placeholder="Search name, generic or barcode…" value="${esc(search)}" autofocus></div></div><div class="product-grid">${state.products.filter(p=>(p.name+' '+p.generic+' '+p.barcode).toLowerCase().includes(search.toLowerCase())).map(p=>`<button class="product-tile" data-add="${p.id}" ${stockQty(p.id)===0?'disabled':''}><span class="product-icon">${icon('box')}</span><strong>${esc(p.name)} ${p.rx?'℞':''}</strong><small>${esc(p.strength)} · ${stockQty(p.id)} units available</small><b>${fmt(Math.round(p.price/r),posCurrency)}</b></button>`).join('')}</div></section><section class="card"><div class="card-head"><h2>Current order</h2><span class="muted">${cart.length} products</span></div><div class="cart"><div class="form-grid">${select('pos-customer','Customer',state.customers.map(c=>[c.id,c.name]),sessionStorage.getItem('pos-customer')||'walkin')}${select('pos-currency','Invoice currency',['USD','ZAR','ZiG'].map(c=>[c,c]),posCurrency)}</div><div class="section-gap">${cart.map((i,idx)=>`<div class="cart-row"><div><strong>${esc(product(i.product_id).name)}</strong><small>${fmt(Math.round(product(i.product_id).price/r),posCurrency)} per unit</small></div><input type="number" min="1" step="1" data-qty="${idx}" aria-label="Quantity" value="${i.quantity}"><strong>${fmt(Math.round(product(i.product_id).price/r)*i.quantity,posCurrency)}</strong><button class="icon-button delete-action" data-remove="${idx}" aria-label="Remove product from cart" title="Remove product">${icon('trash')}</button></div>`).join('')||'<div class="empty">Your order is ready for its first product.</div>'}</div><div class="totals"><div><span>Subtotal</span><span>${fmt(subtotal,posCurrency)}</span></div><div><span>Discount (${posCurrency})</span><input id="discount" type="number" min="0" step="0.01" value="${draftDiscount}" style="width:90px;padding:5px"></div><div><span>Tax (${state.settings.tax}%)</span><span>${fmt(tax,posCurrency)}</span></div><div class="grand"><span>Total</span><span>${fmt(total,posCurrency)}</span></div></div><div class="stack">${input('prescription','Prescription reference (verified by authorized staff)',sessionStorage.getItem('rx')||'')}<div class="row"><h3 class="grow">Payments</h3><button class="small secondary" data-action="add-payment">${icon('plus')} Split payment</button></div>${payments.map((p,i)=>`<div class="row"><span class="grow muted">${esc(state.accounts.find(a=>a.id===p.account_id).name)}</span><strong>${fmt(amount(p.amount),state.accounts.find(a=>a.id===p.account_id).currency)}</strong><button class="icon-button delete-action" data-remove-payment="${i}" aria-label="Remove unposted payment" title="Remove payment">${icon('trash')}</button></div>`).join('')}<div class="form-note">${paid>=total&&total>0?`Change due: <strong>${fmt(paid-total,posCurrency)}</strong>. Enter net payment after giving change.`:`Outstanding: <strong>${fmt(total-paid,posCurrency)}</strong>. Registered customers may buy on credit.`}<br>Rate: 1 ${posCurrency} = ${r} USD · approved ${rate(posCurrency)?.effective}</div><div class="row"><button class="grow" data-checkout="draft">Save draft</button><button class="grow" data-checkout="quote">Quotation</button></div><button class="primary" data-checkout="sale">${icon('check')} Complete sale · ${fmt(total,posCurrency)}</button><p class="muted">Completed sales are corrected with a credit note and return inspection.</p></div></div></section></div>`+foot()}
function inventory(){let ps=state.products.filter(p=>(p.name+' '+p.barcode+' '+p.sku).toLowerCase().includes(search.toLowerCase()));if(subtab==='low')ps=ps.filter(p=>stockQty(p.id)<=p.reorder);let val=state.batches.reduce((s,b)=>s+(b.quantity*(b.cost||0)),0);let batches=state.batches.filter(b=>b.quantity>0);if(subtab==='expiry')batches=batches.filter(b=>b.expiry<=new Date(Date.now()+state.settings.policy.expiryDays*86400000).toISOString().slice(0,10));return head('Pharmaceutical inventory','Trace every unit. Protect product quality. Stay ahead of demand.',`${csvImportButton(['batches','expiry'].includes(subtab)?'batches':'products',icon)}<button data-action="stock-control">${icon('settings')} Stock controls</button><button data-action="receive">${icon('down')} Receive stock</button><button class="primary" data-action="product">${icon('plus')} Add product</button>`)+`<div class="stats">${stat('Inventory value at cost',financial()?display(val):'Restricted','box','','All physical stock · including quarantine')}${stat('Active products',String(state.products.length),'pill','teal','Base sales units · whole unit precision')}${stat('Low stock',String(state.products.filter(p=>stockQty(p.id)<=p.reorder).length),'alert','amber','Includes out-of-stock products')}${stat('Quarantined batches',String(batches.filter(b=>b.status==='quarantine').length),'shield','amber','Unavailable until authorized release')}</div>`+tabButtons([['','Product catalogue'],['low','Low stock'],['batches','Batches'],['expiry','Expiry alerts'],['ledger','Stock ledger']])+`<section class="card"><div class="toolbar"><div class="search">${icon('search')}<input id="search" placeholder="Search products, SKU or barcode…" value="${esc(search)}"></div><button data-action="export-inventory">${icon('down')} Export inventory</button></div>${subtab==='ledger'?stockLedger():['batches','expiry'].includes(subtab)?`<div class="table-scroll"><table><thead><tr><th>Product / batch</th><th>Expiry</th><th>Quantity</th><th>Status</th><th>Action</th></tr></thead><tbody>${batches.filter(b=>(product(b.product_id).name+' '+b.number).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>a.expiry.localeCompare(b.expiry)).map(b=>`<tr><td><strong>${esc(product(b.product_id).name)}</strong><small>${esc(b.number)}</small></td><td>${fullDate(b.expiry)}</td><td>${b.quantity}</td><td>${badge(b.expiry<today()?'Expired':b.status,b.expiry<today()||b.status==='recalled'?'red':b.status==='quarantine'?'amber':'')}</td><td>${b.number.endsWith('-RETURN')&&b.status==='quarantine'?`<button class="text-button" data-inspect="${b.id}">Inspect return</button>`:`<button class="text-button" data-trace="${b.id}">Trace batch</button>`}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No matching batches</td></tr>'}</tbody></table></div>`:`<div class="table-scroll"><table><thead><tr><th>Product</th><th>SKU / barcode</th><th>Category</th><th>Price (USD)</th><th>Available</th><th>Status</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><div class="product-cell"><span class="product-icon">${icon('box')}</span><div><strong>${esc(p.name)} ${p.rx?'℞':''}</strong><small>${esc(p.strength)} · ${esc(p.form)} · ${p.pack_size} units/pack</small></div></div></td><td>${esc(p.sku)}<small>${esc(p.barcode)}</small></td><td>${esc(p.category)}</td><td><strong>${fmt(p.price,'USD')}</strong>${financial()?`<small>Cost ${fmt(p.cost,'USD')}</small>`:''}</td><td><strong>${stockQty(p.id)}</strong><small>Reorder at ${p.reorder}</small></td><td>${badge(!stockQty(p.id)?'Out of stock':stockQty(p.id)<=p.reorder?'Low stock':'In stock',!stockQty(p.id)?'red':stockQty(p.id)<=p.reorder?'amber':'')}</td><td><button class="text-button" data-product="${p.id}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`}</section>`+foot()}
function stockLedger(batch=null){return `<div class="table-scroll"><table><thead><tr><th>Date</th><th>Product / batch</th><th>Movement</th><th>Reason / source</th><th>User</th></tr></thead><tbody>${[...state.movements].filter(m=>(!batch||m.batch_id===batch)&&(product(m.product_id).name+' '+m.reason).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)).map(m=>`<tr><td>${fullDate(m.date)}</td><td><strong>${esc(product(m.product_id).name)}</strong><small>${esc(state.batches.find(b=>b.id===m.batch_id)?.number)}</small></td><td style="color:${m.quantity<0?'#b91c1c':'#15803d'}">${m.quantity>0?'+':''}${m.quantity}</td><td>${esc(m.reason)}</td><td>${esc(m.user_id)}</td></tr>`).join('')}</tbody></table></div>`}
function cashPage(){let m=metrics();return head('Cash flow','A clear view of the money moving through your business.',`<button data-action="pay-supplier">${icon('file')} Pay supplier</button><button data-action="till">${icon('cash')} Manage till</button><button data-action="transfer">${icon('sync')} Transfer</button><button class="primary" data-action="cash-entry">${icon('plus')} Cash entry</button>`)+periodFilter()+`<div class="stats">${stat('Cash received',display(m.cashIn),'down','green','Account inflows · transfers included here')}${stat('Cash paid',display(m.cashOut),'expense','amber','Account outflows · transfers included here')}${stat('Net movement',display(m.cashIn-m.cashOut),'trend','teal','Internal transfers net to zero at booked rates')}${stat('Available balance',display(state.accounts.reduce((s,a)=>s+round(a.balance,rate(a.currency)?.rate||1),0)),'bank','','Current balances · today’s reporting rates')}</div><div class="info-grid">${state.accounts.map(a=>`<div class="card info-card"><div class="row"><span class="stat-icon">${icon(a.kind==='bank'?'bank':'cash')}</span><h2>${esc(a.name)}</h2></div><div class="stat-value">${fmt(a.balance,a.currency)}</div><p>${esc(a.currency)} · ${esc(a.kind)} account</p>${badge(state.tills.some(t=>t.account_id===a.id&&!t.closed)?'Till open':'Reconciled balance','blue')}</div>`).join('')}</div><section class="card section-gap"><div class="table-title"><h2>Account movements</h2><button class="text-button" data-action="export-cash">Export CSV</button></div><div class="table-scroll"><table><thead><tr><th>Date</th><th>Account</th><th>Method</th><th>Original amount</th><th>Frozen USD value</th><th>Reference</th></tr></thead><tbody>${[...state.payments].filter(p=>inPeriod(p.date)).sort((a,b)=>b.date.localeCompare(a.date)).map(p=>`<tr><td>${shortDate(p.date)}</td><td>${esc(state.accounts.find(a=>a.id===p.account_id)?.name)}</td><td>${esc(p.method)}</td><td style="color:${p.direction==='in'?'#15803d':'#b91c1c'}">${p.direction==='in'?'+':'−'}${fmt(p.amount,p.currency)}</td><td>${fmt(p.base_amount,'USD')}<small>Rate ${p.rate}</small></td><td>${esc((p.reference||'').slice(0,28))}</td></tr>`).join('')}</tbody></table></div></section><section class="card section-gap"><div class="table-title"><h2>Till reconciliation history</h2></div><div class="table-scroll"><table><thead><tr><th>Opened</th><th>Account</th><th>Expected</th><th>Counted</th><th>Variance</th><th>Status</th></tr></thead><tbody>${state.tills.map(t=>{const a=state.accounts.find(a=>a.id===t.account_id);return `<tr><td>${shortDate(t.opened)}</td><td>${esc(a.name)}</td><td>${t.expected===null?'—':fmt(t.expected,a.currency)}</td><td>${t.counted===null?'—':fmt(t.counted,a.currency)}</td><td>${t.variance===null?'—':fmt(t.variance,a.currency)}</td><td>${badge(t.closed?'Closed':'Open',t.variance?'amber':'')}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">Open a till to start a reconciliation session</td></tr>'}</tbody></table></div></section>`+foot()}
function expensesPage(){const ds=state.documents.filter(d=>d.kind==='expense'&&inPeriod(d.date)&&(d.supplier+' '+d.category+' '+(d.payload.description||'')).toLowerCase().includes(search.toLowerCase()));return head('Operating expenses','Manage costs without mixing stock purchases or asset acquisitions.',`${csvImportButton('expenses',icon)}<button class="primary" data-action="expense">${icon('plus')} Record expense</button>`)+periodFilter()+`<div class="stats">${stat('Total expenses',display(ds.reduce((s,d)=>s+d.base_total,0)),'expense','amber','Accrual basis · recorded in this period')}${stat('Paid to date',display(ds.reduce((s,d)=>s+round(d.paid,d.rate),0)),'check','green','Payments against these expenses')}${stat('Supplier balances',display(ds.reduce((s,d)=>s+round(d.total-d.paid,d.rate),0)),'file','','Unpaid operating expenses')}${stat('Expense categories',new Set(ds.map(d=>d.category)).size,'grid','teal','Across the selected period')}</div><section class="card"><div class="toolbar"><div class="search">${icon('search')}<input id="search" placeholder="Search description, category or supplier…" value="${esc(search)}"></div><button data-action="export-expenses">${icon('down')} Export CSV</button></div><div class="table-scroll"><table><thead><tr><th>Description</th><th>Supplier</th><th>Category</th><th>Date</th><th>Amount</th><th>Balance</th><th></th></tr></thead><tbody>${ds.map(d=>`<tr><td><strong>${esc(d.payload.description)}</strong><small>${esc(d.number)}</small></td><td>${esc(d.supplier)}</td><td>${esc(d.category)}</td><td>${fullDate(d.date)}</td><td>${fmt(d.total,d.currency)}</td><td>${badge(fmt(d.total-d.paid,d.currency),d.paid<d.total?'amber':'')}</td><td>${d.paid<d.total?`<button class="text-button" data-pay-expense="${d.id}">Make payment</button>`:`<button class="text-button" data-doc="${d.id}">View</button>`}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No matching expenses</td></tr>'}</tbody></table></div></section>`+foot()}
function assetsPage(){return head('Business assets','Keep a complete register of the equipment behind your care.',`${csvImportButton('assets',icon)}<button class="primary" data-action="asset">${icon('plus')} Register asset</button>`)+`<div class="notice">Straight-line depreciation is an informational accrual preview until disposal. Periodic depreciation posting and alternative methods require further implementation.</div><div class="stats">${stat('Acquisition cost',display(state.assets.filter(a=>!a.disposed).reduce((s,a)=>s+round(a.cost,a.rate),0)),'asset','','Active assets · historical rates')}${stat('Accumulated depreciation',display(state.assets.filter(a=>!a.disposed).reduce((s,a)=>s+round(a.depreciation,a.rate),0)),'chart','amber','Straight-line preview to today')}${stat('Net book value',display(state.assets.filter(a=>!a.disposed).reduce((s,a)=>s+round(a.nbv,a.rate),0)),'profit','green','Cost less depreciation preview')}${stat('Registered assets',state.assets.length,'box','teal','Includes disposed assets')}</div><section class="card"><div class="table-title"><h2>Asset register</h2><button class="text-button" data-action="export-assets">Export CSV</button></div><div class="table-scroll"><table><thead><tr><th>Asset</th><th>Location / custodian</th><th>Acquired</th><th>Cost</th><th>Net book value</th><th>Condition</th><th></th></tr></thead><tbody>${state.assets.map(a=>`<tr><td><strong>${esc(a.description)}</strong><small>${esc(a.number)} · ${esc(a.category)}</small></td><td>${esc(a.location)}<small>${esc(a.custodian)}</small></td><td>${fullDate(a.date)}</td><td>${fmt(a.cost,a.currency)}</td><td>${fmt(a.nbv,a.currency)}<small>${a.life} year useful life</small></td><td>${badge(a.disposed?'Disposed':a.condition,a.disposed?'amber':'')}</td><td>${a.disposed?'':`<button class="text-button danger" data-dispose="${a.id}">Dispose</button>`}</td></tr>`).join('')}</tbody></table></div></section>`+foot()}
function profilePage(){return head('My profile','Manage your identity, security and workspace preferences.')+`<div class="settings-layout"><section class="card settings-card"><div class="row" style="margin-bottom:25px"><span class="avatar" style="width:56px;height:56px;font-size:20px">${esc(state.user.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div><h2>${esc(state.user.name)}</h2><p class="muted">${esc(state.user.role)} · Main branch</p></div></div><form id="profile-form" class="stack">${input('name','Full name',state.user.name,'text','required')}${input('email','Email address',state.user.email,'email','required')}${input('current_password','Current password (only when changing password)','','password')}${input('password',state.production?'New password (16 characters minimum)':'New password (12 characters minimum)','','password',state.production?'minlength="16"':'minlength="12"')}<button class="primary">Save profile</button><div class="error" id="profile-error"></div></form></section><section class="card settings-card"><h2>Access & device</h2><p class="muted">Your role is enforced by the server. Financial records cannot be silently deleted.</p><div class="form-note">Device identifier: <strong>${esc(device)}</strong><br>${state.settings.policy.offlineEnabled===false?'Offline transactions are disabled in this production workspace.':'Offline access expires '+state.settings.policy.offlineHours+' hours after the last authorized server session.<br>Permitted offline actions: sales, receipts, expenses, drafts and quotations.'}</div><p class="muted">Locally cached records are stored on this browser. Use an encrypted device with an individual operating-system account.</p><button class="danger" data-action="logout">${icon('logout')} Sign out and clear cached records</button></section></div>`+foot()}
function settingsPage(){const b=state.settings.business,p=state.settings.policy;return head('Workspace settings','Configure your pharmacy’s business and financial controls.')+`<div class="notice">Tax settings, exchange rates and pharmacy workflows must be reviewed against your local operating and regulatory requirements.</div><div class="settings-layout"><section class="card settings-card"><h2>Business details & receipt branding</h2><img class="settings-logo" src="/brand-logo-current.png" alt="Thachi Investiments logo"><form id="business-form" class="stack">${input('name','Business name',b.name,'text','required')}<label>Business address<textarea name="address" rows="3">${esc(b.address)}</textarea></label>${input('email','Email',b.email,'email')}${input('phone','Phone',b.phone)}${input('registration','Registration details',b.registration)}${input('tin','Tax identification number (TIN)',b.tin||'')}${input('invoice_terms','Default invoice terms',b.invoice_terms||'Due Upon Receipt')}<button class="primary">Save business details</button></form></section><section class="card settings-card"><h2>Financial & offline policies</h2><form id="policy-form" class="stack">${input('tax','Default sales tax (%)',state.settings.tax,'number','min="0" max="100" step="0.01" required')}${input('discountLimit','Cashier discount limit (%)',p.discountLimit,'number','min="0" max="100" required')}${input('rateAgeDays','Maximum exchange rate age (days)',p.rateAgeDays,'number','min="1" max="30" required')}${input('expiryDays','Expiry alert window (days)',p.expiryDays,'number','min="1" max="365" required')}${input('offlineDevice','Designated offline terminal',p.offlineDevice,'text','required')}${input('offlineHours','Offline access limit (hours)',p.offlineHours,'number','min="1" max="24" required')}<button class="primary">Save policies</button></form></section><section class="card settings-card"><div class="row"><h2 class="grow">Approved exchange rates</h2><button class="small secondary" data-action="rate">${icon('plus')} Add rate</button></div><p class="muted">USD is the base currency. Rates express USD value of one foreign unit. Historical records never change.</p><table><thead><tr><th>Currency</th><th>Rate to USD</th><th>Effective</th></tr></thead><tbody>${['USD','ZAR','ZiG'].map(c=>`<tr><td>${c}</td><td>${rate(c)?.rate||'Not configured'}</td><td>${rate(c)?.effective||'-'}</td></tr>`).join('')}</tbody></table></section><section class="card settings-card"><h2>Data, reports & recovery</h2><div class="stack"><p class="muted">Download an online SQLite backup when using SQLite. PostgreSQL backups are managed by your database provider. Protect all backups as sensitive business records.</p><button data-action="backup">${icon('down')} Download database backup</button><button data-action="reports">${icon('chart')} Open financial reports</button><button data-action="sync">${icon('sync')} Review sync queue · ${pending()} pending</button><a href="/guide.html" target="_blank">Read the operating guide ↗</a><p class="muted">Restore instructions, production prerequisites and known limitations are included in the project README.</p></div></section></div>`+foot()}
function reportsPage(){let m=metrics();return head('Financial reports','All accounting reports use immutable historical USD equivalents.',`<button data-action="print-report">${icon('print')} Print / save PDF</button><button data-action="export-ledger">${icon('down')} Export ledger</button>`)+periodFilter()+`<div class="card"><div class="table-title"><h2>Profit & loss · USD base</h2><span class="muted">${fullDate(from)} — ${fullDate(to)}</span></div><table><tbody>${[['Gross sales before discounts',m.sales.reduce((s,d)=>s+round(d.subtotal,d.rate),0)],['Net sales (after discounts and credit notes)',m.net],['Cost of goods sold',m.cogs],['Gross profit',m.net-m.cogs],['Operating expenses',m.expenses],['Realized exchange differences',ledgerTotal('fx_gain_loss','credit')],['Posted depreciation',ledgerTotal('depreciation')],['Net profit',m.profit]].map(([n,v])=>`<tr><td><strong>${n}</strong></td><td style="text-align:right">${fmt(v,'USD')}</td></tr>`).join('')}</tbody></table></div><div class="report-grid section-gap">${[['cashflow','Cash-flow statement','Operating, investing and financing flows','cash'],['receivables','Customer receivables','Balances and customer statements','user'],['payables','Supplier payables','Stock invoices and expense balances','file'],['valuation','Inventory valuation','All physical stock at batch cost','box'],['expiry','Expiry report','Expired and expiring batches','clock'],['trial','Trial balance','Debit and credit control totals','bank'],['audit','Audit trail','Actions, approvals and timestamps','shield']].map(([id,n,d,i])=>`<button class="card report-tile" data-report="${id}"><span class="stat-icon">${icon(i)}</span><strong>${n}</strong><small>${d}</small></button>`).join('')}</div>`+foot()}
function render(){if(!state){login();return}if(!rate(currency)){currency='USD';localStorage.setItem('currency','USD')}$('#app').innerHTML=shell();let page={dashboard,sales:salesPage,cash:cashPage,inventory,expenses:expensesPage,assets:assetsPage,profile:profilePage,settings:settingsPage,reports:reportsPage}[route]||dashboard;if(!financial()&&['dashboard','cash','assets','expenses','settings','reports'].includes(route))$('#main').innerHTML=head('Your pharmacy workspace','Use Sales and Inventory to perform the tasks allowed by your role.')+`<div class="card empty">${icon('shield')} Financial access requires a manager or accountant role.<p><button class="primary" data-action="pos">Create a new sale</button></p></div>`;else $('#main').innerHTML=page();bind()}
function openInvoice(id){selectedInvoiceId=id;route='sales';subtab='detail';search='';location.hash='sales/invoice/'+encodeURIComponent(id);render()}
function openImporter(dataset){openCsvImport(dataset,{state,api,submit,modal,toast,icon,badge,download,exportCsv:csvDownload})}
function bind(){
    $$('[data-invoice-view]').forEach(b=>b.onclick=()=>openInvoice(b.dataset.invoiceView));
    $$('[data-invoice-back]').forEach(b=>b.onclick=()=>navTo('sales','invoices'));
    $$('[data-invoice-pdf]').forEach(b=>b.onclick=()=>viewDoc(b.dataset.invoicePdf));
    $$('[data-invoice-print]').forEach(b=>b.onclick=()=>{viewDoc(b.dataset.invoicePrint);$('#a4').click()});
    $$('[data-invoice-pay]').forEach(b=>b.onclick=()=>payDocument(b.dataset.invoicePay));
    $$('[data-invoice-customer]').forEach(b=>b.onclick=()=>statement(b.dataset.invoiceCustomer));
    $$('[data-invoice-related]').forEach(b=>b.onclick=()=>openInvoice(b.dataset.invoiceRelated));
    $$('[data-invoice-delivery]').forEach(b=>b.onclick=()=>deliveryNote(b.dataset.invoiceDelivery));
    $$('[data-invoice-email]').forEach(b=>b.onclick=()=>emailDocument(b.dataset.invoiceEmail));
    $$('[data-invoice-credit]').forEach(b=>b.onclick=()=>form('Issue full credit note',`<input name="document_id" type="hidden" value="${b.dataset.invoiceCredit}">${input('reason','Reason for full reversal','','text','required minlength="4"')}`,'refund',x=>x,'Reverses the complete sale. Original payments are refunded and returned stock enters quarantine for inspection.'));

    $$('[data-import]').forEach(b=>{b.disabled=!canImport(b.dataset.import,state.user.role);b.title=b.disabled?'Your role does not permit this import':'Upload '+b.dataset.import+' from CSV';b.onclick=()=>openImporter(b.dataset.import)});
    $$('[data-nav-group]').forEach(group=>group.addEventListener('toggle',()=>sessionStorage.setItem('nav-group-'+group.dataset.navGroup,group.open?'open':'closed')));
    $$('[data-route]').forEach(b=>b.onclick=()=>navTo(b.dataset.route,b.dataset.tab||''));
    $$('[data-period]').forEach(b=>b.onclick=()=>{period=b.dataset.period;dates(period);render()});
    $$('[data-tab]:not([data-route])').forEach(b=>b.onclick=()=>{subtab=b.dataset.tab;search='';render()});
    $$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
    const actionRoles={receive:['super_admin','admin','manager','stock'],product:['super_admin','admin','manager','stock'],'stock-control':['super_admin','admin','manager','stock','pharmacist'],expense:['super_admin','admin','manager','accountant'],asset:['super_admin','admin','manager','accountant'],transfer:['super_admin','admin','manager','accountant'],'cash-entry':['super_admin','admin','manager','accountant'],'pay-supplier':['super_admin','admin','manager','accountant'],rate:['super_admin','admin','manager','accountant'],backup:['super_admin','admin']};for(let b of $$('[data-action]')){let roles=actionRoles[b.dataset.action];if(roles&&!roles.includes(state.user.role)){b.disabled=true;b.title='Your role does not permit this action'}}
    $('#menu').onclick=()=>$('aside').classList.toggle('open');$('#notifications').onclick=()=>syncModal();
    $('#currency').onchange=e=>{if(!rate(e.target.value)){e.target.value=currency;toast('No approved exchange rate is configured for that currency. Ask a manager to add one.',true);return}currency=e.target.value;localStorage.setItem('currency',currency);render()};
    if($('#from'))$('#from').onchange=e=>{if(e.target.value>to)return toast('Start date must be before end date',true);from=e.target.value;period='custom';render()};
    if($('#to'))$('#to').onchange=e=>{if(e.target.value<from)return toast('End date must follow start date',true);to=e.target.value;period='custom';render()};
    if($('#search'))$('#search').oninput=e=>{let pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};
    if($('#product-search')){$('#product-search').oninput=e=>{let pos=e.target.selectionStart;search=e.target.value;render();$('#product-search').focus();$('#product-search').setSelectionRange(pos,pos)};$('#product-search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();let p=state.products.find(p=>p.barcode===e.target.value);if(p){addCart(p.id);search='';render()}}}}
    $$('[data-add]').forEach(b=>b.onclick=()=>addCart(b.dataset.add));
    $$('[data-qty]').forEach(b=>b.onchange=e=>{const q=Number(e.target.value);if(!Number.isInteger(q)||q<1)return toast('Enter a whole unit quantity',true);cart[Number(b.dataset.qty)].quantity=q;render()});
    $$('[data-remove]').forEach(b=>b.onclick=async()=>{const index=Number(b.dataset.remove),name=product(cart[index].product_id).name;if(!await ask({title:'Remove this item?',message:'Do you really want to remove '+name+' from this sale?',confirmLabel:'Remove item'}))return;cart.splice(index,1);render();toast('Item removed from the cart.')});
    $$('[data-remove-payment]').forEach(b=>b.onclick=async()=>{if(!await ask({title:'Remove this payment?',message:'Do you really want to remove this unposted payment from the current sale?',confirmLabel:'Remove payment'}))return;payments.splice(Number(b.dataset.removePayment),1);render();toast('Unposted payment removed.')});
    $$('[data-checkout]').forEach(b=>b.onclick=()=>checkout(b.dataset.checkout,b));
    if($('#discount'))$('#discount').onchange=e=>{draftDiscount=Number(e.target.value);render()};
    if($('[name=pos-currency]'))$('[name=pos-currency]').onchange=e=>{if(!rate(e.target.value)){e.target.value=posCurrency;toast('An approved exchange rate is required before using that currency.',true);return}posCurrency=e.target.value;payments=[];render()};
    if($('[name=pos-customer]'))$('[name=pos-customer]').onchange=e=>sessionStorage.setItem('pos-customer',e.target.value);
    if($('[name=prescription]'))$('[name=prescription]').oninput=e=>sessionStorage.setItem('rx',e.target.value);
    $$('[data-doc]').forEach(b=>b.onclick=()=>b.dataset.invoiceView?openInvoice(b.dataset.invoiceView):viewDoc(b.dataset.doc));
    $$('[data-delete-doc]').forEach(b=>b.onclick=()=>deleteDocument(b.dataset.deleteDoc));
    $$('[data-void-sale]').forEach(b=>b.onclick=()=>voidSale(b.dataset.voidSale));
    $$('[data-pay-expense]').forEach(b=>b.onclick=()=>payDocument(b.dataset.payExpense));
    $$('[data-product]').forEach(b=>b.onclick=()=>viewProduct(b.dataset.product));
    $$('[data-trace]').forEach(b=>b.onclick=()=>modal('Batch traceability',stockLedger(b.dataset.trace),true));
    $$('[data-inspect]').forEach(b=>b.onclick=()=>form('Inspect returned stock',`<input type="hidden" name="batch_id" value="${b.dataset.inspect}">${select('decision','Inspection decision',[['release','Release for resale'],['reject','Reject and write off']])}${input('reason','Inspection findings','','text','required minlength="4"')}`,'inspect'));
    $$('[data-dispose]').forEach(b=>b.onclick=()=>form('Dispose asset',`<input type="hidden" name="asset_id" value="${b.dataset.dispose}">${input('proceeds','Disposal proceeds',0,'number','min="0" step="0.01" required')}${select('account_id','Receipt account',accountsOptions())}`,'dispose'));
    $$('[data-statement]').forEach(b=>b.onclick=()=>statement(b.dataset.statement));
    $$('[data-report]').forEach(b=>b.onclick=()=>report(b.dataset.report));
    if($('#business-form'))$('#business-form').onsubmit=async e=>{e.preventDefault();try{await submit('settings',{business:{...state.settings.business,...Object.fromEntries(new FormData(e.target))}})}catch(err){toast(err.message,true)}};
    if($('#policy-form'))$('#policy-form').onsubmit=async e=>{e.preventDefault();let p=Object.fromEntries(new FormData(e.target));let tax=Number(p.tax);delete p.tax;for(let k of ['rateAgeDays','discountLimit','expiryDays','offlineHours'])p[k]=Number(p[k]);try{await submit('settings',{tax,policy:{...state.settings.policy,...p}})}catch(err){toast(err.message,true)}};
    if($('#profile-form'))$('#profile-form').onsubmit=async e=>{e.preventDefault();try{let change=!!e.target.password.value;if(change&&pending())throw Error('Synchronize all pending transactions before changing your password.');if(change&&!await ask({title:'Change your password?',message:'Your current sessions will end. Sign in again with the new password to authorize this device.',confirmLabel:'Change password',danger:false}))return;await submit('profile',Object.fromEntries(new FormData(e.target)));let meta=await rawGet('vault');if(meta){meta.email=state.user.email;await rawPut('vault',meta)}if(change){token=null;state=null;sessionStorage.clear();for(let key of ['token','state','queue','lastSync','vault'])await rawPut(key,null);vaultKey=null;render()}}catch(err){if($('#profile-error'))$('#profile-error').textContent=err.message;else toast(err.message,true)}};
}
function addCart(id){let p=product(id),i=cart.find(x=>x.product_id===id),qty=(i?.quantity||0)+1;if(qty>stockQty(id))return toast('Not enough eligible stock',true);if(i)i.quantity++;else cart.push({product_id:id,quantity:1});render()}
async function checkout(kind,b){b.disabled=true;try{let cust=$('[name=pos-customer]').value;let r=rate(posCurrency);if(!r)throw Error('An approved exchange rate is required for this invoice currency.');let subtotal=cart.reduce((s,i)=>s+Math.round(product(i.product_id).price/Number(r.rate))*i.quantity,0);let total=round(subtotal-amount(draftDiscount),1+Number(state.settings.tax)/100);let paid=payments.reduce((s,p)=>s+Math.round(amount(p.amount)*Number(rate(state.accounts.find(a=>a.id===p.account_id).currency).rate)/Number(r.rate)),0);if(paid>total)throw Error('Payments exceed the invoice. Remove the excess payment and enter net tender after change.');const quoteReference=sessionStorage.getItem('quote-reference');const payload={items:cart,customer_id:cust,currency:posCurrency,rate_id:r.id,discount:draftDiscount,prescription:$('[name=prescription]').value,payments:kind==='sale'?payments:[],due:today(),...(kind==='sale'&&quoteReference?{reference:'Converted from quotation '+quoteReference}:{})};const result=await submit(kind,payload);if(quoteReference)sessionStorage.removeItem('quote-reference');cart=[];payments=[];draftDiscount=0;sessionStorage.removeItem('rx');navTo('sales');if(!result.offline)viewDoc(result.id);else offlineReceipt(result.id,payload,total)}catch(err){toast(err.message,true)}finally{b.disabled=false}}
function action(a){
    if(a==='pos'){subtab='pos';navTo('sales','pos');return}
    if(a==='reports'){navTo('reports');return}
    if(a==='sync'){syncModal();return}
    if(a==='stock-control'){modal('Batch controls',`<div class="stack"><button id="batch-state">Recall / quarantine / release</button><button id="stock-count">Count / damage / expiry adjustment</button><p class="muted">Every operation requires an online authorized role and a reason. Physical counts create a balanced stock loss or gain entry.</p></div>`);$('#batch-state').onclick=()=>form('Change batch status',select('batch_id','Batch',state.batches.map(b=>[b.id,product(b.product_id).name+' ? '+b.number+' ? '+b.status]))+select('status','New status',[['quarantine','Quarantine'],['recalled','Recalled'],['available','Available']])+input('reason','Reason','','text','required minlength="4"'),'batch_status');$('#stock-count').onclick=()=>form('Record stock count',select('batch_id','Batch',state.batches.map(b=>[b.id,product(b.product_id).name+' ? '+b.number+' ? '+b.quantity+' units']))+input('counted','Actual units remaining','','number','min="0" step="1" required')+input('reason','Reason / damaged / expired stock reference','','text','required minlength="4"'),'adjust');return}
    if(a==='pay-supplier'){const invoices=state.documents.filter(d=>['expense','purchase'].includes(d.kind)&&d.total>d.paid);if(!invoices.length)return toast('No unpaid supplier invoices');form('Supplier payment',select('document_id','Supplier invoice',invoices.map(d=>[d.id,d.supplier+' ? '+d.number+' ? '+fmt(d.total-d.paid,d.currency)]))+select('account_id','Payment account',accountsOptions())+input('amount','Amount in payment account currency','','number','min="0.01" step="0.01" required')+input('reference','Payment reference'),'expense_payment');return}
    if(a==='customer'){form('Add customer',input('name','Customer / organization name','','text','required')+input('email','Email','','email')+input('phone','Phone')+'<label class="full">Billing address<textarea name="address" rows="3" placeholder="BLUFFHILL INDUSTRIAL PARK&#10;HARARE"></textarea></label>','customer');return}
    if(a==='add-payment'){modal('Add payment',`<form id="payment-form" class="stack">${select('account_id','Payment account',accountsOptions())}${select('method','Payment method',[['cash','Cash'],['bank','Bank transfer'],['card','Card'],['mobile','Mobile money']])}${input('amount','Net amount received (in account currency)','','number','min="0.01" step="0.01" required')}<div class="form-note">For cash tender, give change and record only the amount retained. Different currencies are converted using the approved rate shown in Settings.</div><button class="primary">Add payment</button></form>`);$('#payment-form').onsubmit=e=>{e.preventDefault();let p=Object.fromEntries(new FormData(e.target));const approved=rate(state.accounts.find(a=>a.id===p.account_id).currency);if(!approved){toast('An approved exchange rate is required for this payment account.',true);return}p.rate_id=approved.id;payments.push(p);$('#modal').close();render()};return}
    if(a==='expense'){form('Record expense',input('description','Description','','text','required')+input('supplier','Supplier','','text','required')+select('category','Category',['Rent','Utilities','Salaries','Transport','Maintenance','Insurance','Other'].map(x=>[x,x]))+select('currency','Currency',['USD','ZAR','ZiG'].map(x=>[x,x]))+input('amount','Total amount including tax','','number','min="0.01" step="0.01" required')+input('tax','Included tax amount',0,'number','min="0" step="0.01"')+input('paid','Payment now (in account currency)',0,'number','min="0" step="0.01"')+select('account_id','Payment account',accountsOptions())+input('due','Due date',today(),'date')+input('reference','Receipt / supporting document reference'),'expense',x=>x,'Inventory purchases belong in Inventory → Receive stock. Asset purchases belong in Assets. Expenses post immediately; only manager/accountant roles may record them.');return}
    if(a==='transfer'){form('Account transfer',select('account_id','From account',accountsOptions())+select('to_account','To account',accountsOptions())+input('amount','Amount sent (source currency)','','number','min="0.01" step="0.01" required')+input('received','Amount received (destination currency)','','number','min="0.01" step="0.01" required')+input('reference','Transfer reference'),'transfer',x=>x,'Owned-account transfers do not create revenue or operating expenses. Differences are posted to realized exchange differences.');return}
    if(a==='cash-entry'){form('Cash entry',select('category','Transaction type',[['contribution','Owner contribution'],['drawing','Owner drawing'],['loan','Loan received'],['repayment','Principal repayment']])+select('account_id','Account',accountsOptions())+input('amount','Amount (account currency)','','number','min="0.01" step="0.01" required')+input('reference','Reference','','text','required'),'cash');return}
    if(a==='receive'){form('Receive stock',select('product_id','Product',state.products.map(p=>[p.id,p.name+' '+p.strength]))+input('supplier','Supplier','','text','required')+input('number','Batch number','','text','required')+input('expiry','Expiry date','','date','required min="'+today()+'"')+input('quantity','Quantity in individual sales units','','number','min="1" step="1" required')+input('cost','Unit cost (USD)','','number','min="0.01" step="0.01" required')+select('status','Stock status',[['available','Available'],['quarantine','Quarantine'],['recalled','Recalled']]),'stock',x=>x,'All quantities are base sales units. For 5 packs of 10 tablets, receive 50 units. This creates a supplier payable; settle the supplier invoice from Reports ? Supplier payables.');return}
    if(a==='product'){form('Add product',input('name','Product name','','text','required')+input('generic','Generic name')+input('brand','Brand')+input('manufacturer','Manufacturer')+input('supplier','Supplier')+input('sku','SKU','','text','required')+input('barcode','Barcode','','text','required')+input('category','Category')+input('strength','Strength')+select('form','Dosage / sales unit',['Tablet','Capsule','Sachet','Bottle','Inhaler','Unit'].map(x=>[x,x]))+input('pack_size','Units per purchase pack',10,'number','min="1" step="1" required')+input('cost','Unit cost (USD)','','number','min="0.01" step="0.01" required')+input('price','Unit price (USD)','','number','min="0.01" step="0.01" required')+input('reorder','Reorder level (units)',10,'number','min="1" step="1" required')+input('location','Storage location','Main store')+select('rx','Prescription requirement',[['','Over the counter'],['yes','Prescription only']]),'product',x=>({...x,rx:!!x.rx}));return}
    if(a==='asset'){form('Register asset',input('description','Description','','text','required')+select('category','Category',['Equipment','Cold chain','Computers','Furniture','Vehicles'].map(x=>[x,x]))+input('date','Acquisition date',today(),'date','required max="'+today()+'"')+input('cost','Acquisition cost','','number','min="0.01" step="0.01" required')+select('currency','Currency',['USD','ZAR','ZiG'].map(x=>[x,x]))+select('account_id','Payment account',accountsOptions())+input('location','Location')+input('custodian','Custodian')+input('life','Useful life (years)',5,'number','min="1" max="50" required')+input('residual','Residual value',0,'number','min="0" step="0.01" required')+input('notes','Supporting document / notes'),'asset',x=>x,'Asset purchases are capitalized separately from operating expenses. The payment account must match the asset currency.');return}
    if(a==='rate'){form('Approve exchange rate',select('currency','Currency',[['ZAR','South African rand (ZAR)'],['ZiG','Zimbabwe Gold (ZiG)']])+input('rate','USD per 1 foreign unit','','number','min="0.00000001" step="0.00000001" required')+input('effective','Effective date',today(),'date','required')+input('source','Rate source','Manager approved','text','required'),'rate',x=>x,'Rates are append-only. Existing invoices and payments retain their original rate. No external rate provider is connected.');return}
    if(a==='till'){form('Till reconciliation',select('account_id','Cash drawer',state.accounts.filter(a=>a.kind==='cash').map(a=>[a.id,a.name+' · '+a.currency]))+select('action','Action',[['open','Open till'],['close','Close and reconcile']])+input('counted','Counted cash (for closing)',0,'number','min="0" step="0.01"'),'till',x=>x,'Opening value is the current ledger balance. Closing compares the physical count with the expected balance. Variances are retained for investigation, without silently changing the ledger.');return}
    if(a==='backup'){downloadBackup();return}
    if(a==='logout'){logout();return}
    if(a==='print-report'){modal('Profit & loss',`<div class="receipt"><img class="print-logo" src="/brand-logo-current.png" alt="Thachi Investiments logo"><h1>${esc(state.settings.business.name)}</h1><p>Profit & loss · USD · ${fullDate(from)} – ${fullDate(to)}</p>${$('#main .card').innerHTML}</div><div class="print-actions"><button class="primary" id="print-now">Print / save PDF</button></div>`,true);$('#print-now').onclick=()=>window.print();return}
    if(a.startsWith('export-')){let kind=a.slice(7);let data={sales:state.documents.filter(d=>['sale','refund','quote'].includes(d.kind)&&inPeriod(d.date)).map(({payload,...d})=>d),expenses:state.documents.filter(d=>d.kind==='expense'&&inPeriod(d.date)).map(({payload,...d})=>d),inventory:state.products.map(p=>({...p,available:stockQty(p.id)})),cash:state.payments.filter(p=>inPeriod(p.date)),assets:state.assets,ledger:state.journals.filter(j=>inPeriod(j.date))}[kind];csvDownload(kind,data);return}
}
async function downloadBackup(){if(state.database_backend==='postgresql'){toast('Database backups are managed by your PostgreSQL provider.');return}try{let r=await fetch('/api/backup',{headers:{Authorization:'Bearer '+token}});if(!r.ok)throw Error((await r.json()).error);download('medledger-'+today()+'.sqlite',await r.blob());toast('Backup downloaded. Store it securely.')}catch(e){toast(e.message,true)}}
async function logout(){if(pending()){toast('Resolve or synchronize pending transactions before signing out.',true);syncModal();return}if(!await ask({title:'Sign out on this device?',message:'Locally cached records will be cleared. Your saved server records will be preserved.',confirmLabel:'Sign out',danger:false}))return;try{await api('logout',{})}catch{}authGeneration++;idleSession.stop();token=null;state=null;queue=[];sessionStorage.clear();for(let k of ['state','token','queue','lastSync'])await rawPut(k,null);await rawPut('vault',null);vaultKey=null;render()}
function csvDownload(name,data){if(!data?.length)return toast('No rows to export');let keys=Object.keys(data[0]);const cell=v=>'"'+String(typeof v==='object'?JSON.stringify(v):v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';let csv='\ufeff'+[keys.map(cell).join(','),...data.map(row=>keys.map(k=>cell(row[k])).join(','))].join('\r\n');download(name+'-'+today()+'.csv',new Blob([csv],{type:'text/csv;charset=utf-8'}))}
function download(name,blob){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
function viewProduct(id){let p=product(id);modal(p.name,`<div class="form-grid">${Object.entries({Generic:p.generic,Brand:p.brand,Manufacturer:p.manufacturer,Supplier:p.supplier,SKU:p.sku,Barcode:p.barcode,Strength:p.strength,Form:p.form,'Units per pack':p.pack_size,Location:p.location,'Prescription required':p.rx?'Yes':'No','Available units':stockQty(id)}).map(([k,v])=>`<div><p class="muted">${k}</p><strong>${esc(v)}</strong></div>`).join('')}</div><h3 class="section-gap">Batch history</h3>${stockLedgerForProduct(id)}`,true)}
function stockLedgerForProduct(id){return `<table><thead><tr><th>Batch</th><th>Expiry</th><th>Units</th><th>Status</th></tr></thead><tbody>${state.batches.filter(b=>b.product_id===id).map(b=>`<tr><td>${esc(b.number)}</td><td>${fullDate(b.expiry)}</td><td>${b.quantity}</td><td>${esc(b.status)}${b.expiry<today()?' · expired':''}</td></tr>`).join('')}</tbody></table>`}
function payDocument(id){const d=state.documents.find(d=>d.id===id);form(['expense','purchase'].includes(d.kind)?'Supplier payment':'Customer payment',`<input type="hidden" name="document_id" value="${id}">${select('account_id','Payment account',accountsOptions())}${input('amount','Amount (payment account currency)','','number','min="0.01" step="0.01" required')}${input('reference','Payment reference')}`,['expense','purchase'].includes(d.kind)?'expense_payment':'receipt',x=>x,`Outstanding: ${fmt(d.total-d.paid,d.currency)}. The invoice’s historical rate is retained; settlement differences are posted to exchange differences.`)}
function deliveryNote(id){modal('Delivery note',renderDeliveryNote({id,state})+`<div class="print-actions"><button class="primary" id="print-delivery-note">${icon('print')} Print / save PDF</button></div>`,true);$('#print-delivery-note').onclick=()=>{document.body.classList.remove('thermal');window.print()}}
function emailDocument(id){const d=state.documents.find(d=>d.id===id);if(!d)return toast('Document not found',true);const client=state.customers.find(c=>c.id===d.customer_id)||{},title=d.kind==='quote'?'Quotation':'Invoice';modal('Email '+title.toLowerCase(),`<form id="email-document-form" class="stack"><label>To<input name="to" type="email" value="${esc(client.email||'')}" required></label><label>Subject<input name="subject" value="${esc(title+' '+d.number+' from '+state.settings.business.name)}" maxlength="200" required></label><label>Message (optional)<textarea name="message" rows="4" maxlength="10000" placeholder="Add a note for the customer"></textarea></label><p class="muted">The email includes the ${title.toLowerCase()} number, date, total, paid amount and balance. It does not attach a PDF.</p><div class="error" id="email-document-error" role="alert"></div><div class="form-actions"><button type="button" data-cancel>Email later</button><button class="primary" type="submit">${icon('mail')} Send email</button></div></form>`);$('#email-document-form [data-cancel]').onclick=()=>$('#modal').close();$('#email-document-form').onsubmit=async e=>{e.preventDefault();const submit=e.submitter;submit.disabled=true;try{await api('email-document',{id,...Object.fromEntries(new FormData(e.target))});$('#modal').close();toast('Email sent to '+e.target.elements.to.value)}catch(error){$('#email-document-error').textContent=error.message}finally{submit.disabled=false}}}
async function deleteDocument(id){const d=state.documents.find(d=>d.id===id);if(!d||!['quote','draft'].includes(d.kind))return toast('Only quotations and saved drafts can be deleted.',true);if(!navigator.onLine)return toast('Connect to the server to delete this document.',true);if(!await ask({title:'Delete this '+(d.kind==='quote'?'quotation':'saved draft')+'?',message:d.number+' will be removed from the workspace. This action cannot be undone.',confirmLabel:'Delete document',danger:true}))return;try{const result=await api('delete-document',{id});state=result.state;await put('state',state);if($('#modal').open)$('#modal').close();render();toast('Document deleted.')}catch(error){toast(error.message,true)}}
function voidSale(id){const d=state.documents.find(doc=>doc.id===id);if(!d||d.kind!=='sale'||d.status==='reversed')return toast('Only an active invoice can be voided.',true);form('Void invoice · '+d.number,`<input type="hidden" name="document_id" value="${esc(id)}">${input('reason','Reason for voiding this invoice','','text','required minlength="4"')}`,'refund',x=>x,'The invoice stays in the audit trail. A full credit note reverses the sale, refunds recorded payments and returns stock to quarantine for inspection.')}
function proforma(id){const d=state.documents.find(d=>d.id===id);if(!d||d.kind!=='quote')return toast('Only quotations can be prepared as proforma invoices.',true);const doc={...d,kind:'proforma'};modal('Proforma invoice · '+d.number,renderInvoice({document:doc,state,formatMoney:fmt})+`<div class="print-actions"><button class="primary" id="print-proforma">${icon('print')} Print / save PDF</button></div>`,true);$('#print-proforma').onclick=()=>{document.body.classList.remove('thermal');window.print()}}
function viewDoc(id){const d=state.documents.find(d=>d.id===id);if(!d)return toast('Document not found',true);let p=d.payload,items=p.items||[],r=Number(d.rate),business=state.settings.business;let paymentRows=state.payments.filter(x=>x.document_id===id);modal(d.number,`${renderInvoice({document:d,state,formatMoney:fmt})}<div class="print-actions"><button id="thermal">Thermal receipt</button><button id="a4">${icon('print')} A4 / save PDF</button>${d.kind==='sale'&&d.status!=='reversed'?`<button data-modal-delivery="${d.id}">${icon('truck')} Delivery note</button>`:''}${d.kind==='quote'?`<button class="secondary" id="make-proforma">${icon('file')} Proforma invoice</button>`:''}${d.kind==='sale'&&d.status!=='reversed'&&d.paid<d.total?'<button class="primary" id="receipt-payment">Receive payment</button>':''}${d.kind==='sale'&&d.status!=='reversed'&&['super_admin','admin','manager'].includes(state.user.role)?'<button class="danger" id="refund">Issue full credit</button>':''}${['quote','draft'].includes(d.kind)?`<button class="primary" id="load-draft">${d.kind==='quote'?'Convert to invoice':'Create sale from draft'}</button><button class="danger" id="delete-current-doc">${icon('trash')} Delete ${d.kind==='quote'?'quotation':'draft'}</button>`:''}</div>`,true);document.body.classList.remove('thermal');$('#a4').onclick=()=>{document.body.classList.remove('thermal');window.print()};$('#thermal').onclick=()=>{document.body.classList.add('thermal');window.print()};if($('[data-modal-delivery]'))$('[data-modal-delivery]').onclick=()=>deliveryNote(id);if($('#make-proforma'))$('#make-proforma').onclick=()=>proforma(id);if($('#delete-current-doc'))$('#delete-current-doc').onclick=()=>deleteDocument(id);if($('#receipt-payment'))$('#receipt-payment').onclick=()=>payDocument(id);if($('#refund'))$('#refund').onclick=()=>form('Issue full credit note',`<input name="document_id" type="hidden" value="${id}">${input('reason','Reason for full reversal','','text','required minlength="4"')}`,'refund',x=>x,'This reverses the complete sale and refunds original payments to their original accounts. Returned stock enters quarantine for inspection. Manager authorization is recorded.');if($('#load-draft'))$('#load-draft').onclick=()=>{if(items.some(i=>!product(i.product_id))){toast('This document contains removed products. Its saved details remain available; create a new sale using the current catalogue.',true);return}if(d.kind==='quote')sessionStorage.setItem('quote-reference',d.number);cart=structuredClone(items);draftDiscount=d.discount/100;posCurrency=d.currency;payments=[];sessionStorage.setItem('pos-customer',d.customer_id);$('#modal').close();navTo('sales','pos')}}
function offlineReceipt(id,p,total){
 const invoiceRate=state.rates.find(r=>r.id===p.rate_id)||rate(p.currency),fx=Number(invoiceRate.rate);
 const subtotal=p.items.reduce((sum,item)=>sum+Math.round(product(item.product_id).price/fx)*Number(item.quantity),0),discount=amount(p.discount||0);
 const localPayments=(p.payments||[]).map((payment,i)=>{const account=state.accounts.find(a=>a.id===payment.account_id),paymentRate=state.rates.find(r=>r.id===payment.rate_id)||rate(account.currency);return {id:id+'-'+i,document_id:id,account_id:account.id,date:new Date().toISOString(),amount:amount(payment.amount),currency:account.currency,rate:paymentRate.rate,method:payment.method||account.kind,direction:'in'}});
 const paid=localPayments.reduce((sum,payment)=>sum+Math.round(payment.amount*Number(payment.rate)/fx),0);
 const doc={id,number:'OFF-'+id.slice(0,8).toUpperCase(),kind:'offline',date:new Date().toISOString(),customer_id:p.customer_id,currency:p.currency,rate:invoiceRate.rate,subtotal,discount,tax:total-subtotal+discount,total,paid,status:'pending',due:p.due,payload:{...p,tax_rate:state.settings.tax}};
 const localState={...state,payments:[...state.payments,...localPayments]};
 modal('Offline transaction saved',renderInvoice({document:doc,state:localState,formatMoney:fmt})+`<div class="print-actions"><button id="offline-print" class="primary">${icon('print')} Print receipt / save PDF</button></div>`,true);
 $('#offline-print').onclick=()=>{document.body.classList.remove('thermal');window.print()};
}

function statement(id){const docs=state.documents.filter(d=>d.customer_id===id&&['sale','refund'].includes(d.kind)).sort((a,b)=>a.date.localeCompare(b.date));const due=docs.filter(d=>d.kind==='sale'&&d.status!=='reversed').reduce((s,d)=>s+round(d.total-d.paid,d.rate),0);modal('Customer statement',`<article class="receipt"><img class="print-logo" src="/brand-logo-current.png" alt="Thachi Investiments logo"><h1>${esc(state.settings.business.name)}</h1><h2>${esc(customer(id))}</h2><p>Statement as of ${fullDate(today())} · historical USD equivalents</p><table><thead><tr><th>Document</th><th>Date</th><th>Original total</th><th>Paid</th><th>Status</th></tr></thead><tbody>${docs.map(d=>`<tr><td>${esc(d.number)}</td><td>${shortDate(d.date)}</td><td>${fmt(d.total,d.currency)}</td><td>${fmt(d.paid,d.currency)}</td><td>${esc(d.status)}</td></tr>`).join('')}</tbody></table><h2 class="section-gap">Outstanding ${fmt(due,'USD')}</h2></article><div class="print-actions"><button id="statement-print">Print / save PDF</button><button id="statement-csv">Export CSV</button></div>`,true);$('#statement-print').onclick=()=>window.print();$('#statement-csv').onclick=()=>csvDownload('statement',docs.map(({payload,...d})=>d))}
function report(kind){let title='',data=[];if(kind==='cashflow'){title='Cash-flow statement ? historical USD';let groups={};for(let j of state.journals.filter(j=>inPeriod(j.date))){groups[j.source_id]??=[];groups[j.source_id].push(j)}let totals={Operating:{in:0,out:0},Investing:{in:0,out:0},Financing:{in:0,out:0}};for(let [source,entries] of Object.entries(groups)){let type=(state.event_types||[]).find(e=>e.id===source)?.kind;if(type==='transfer'||source.startsWith('opening'))continue;let value=entries.filter(j=>state.accounts.some(a=>a.id===j.account)).reduce((s,j)=>s+j.debit-j.credit,0);if(!value)continue;let category=['asset','dispose'].includes(type)?'Investing':entries.some(j=>['equity','loan_payable'].includes(j.account))?'Financing':'Operating';totals[category][value>0?'in':'out']+=Math.abs(value)}data=Object.entries(totals).map(([category,v])=>({Category:category,'Cash received USD':(v.in/100).toFixed(2),'Cash paid USD':(v.out/100).toFixed(2),'Net cash USD':((v.in-v.out)/100).toFixed(2)}))};if(kind==='receivables'){title='Customer receivables';data=state.documents.filter(d=>d.kind==='sale'&&d.status!=='reversed'&&d.total>d.paid).map(d=>({Customer:customer(d.customer_id),Invoice:d.number,Currency:d.currency,Total:d.total/100,Paid:d.paid/100,Balance:(d.total-d.paid)/100,USD:round(d.total-d.paid,d.rate)/100,Due:d.due}))}if(kind==='payables'){title='Supplier payables';data=state.documents.filter(d=>['expense','purchase'].includes(d.kind)&&d.total>d.paid).map(d=>({Supplier:d.supplier,Invoice:d.number,Type:d.kind,Currency:d.currency,Balance:(d.total-d.paid)/100,USD:round(d.total-d.paid,d.rate)/100}))}if(kind==='valuation'){title='Inventory valuation';data=state.batches.filter(b=>b.quantity).map(b=>({Product:product(b.product_id).name,Batch:b.number,Status:b.status,Expiry:b.expiry,Units:b.quantity,'Unit cost USD':b.cost/100,'Value USD':b.cost*b.quantity/100}))}if(kind==='expiry'){title='Expiry report';data=state.batches.filter(b=>b.quantity&&b.expiry<=new Date(Date.now()+state.settings.policy.expiryDays*86400000).toISOString().slice(0,10)).map(b=>({Product:product(b.product_id).name,Batch:b.number,Expiry:b.expiry,Units:b.quantity,Status:b.expiry<today()?'Expired':b.status}))}if(kind==='trial'){title='Trial balance · period movement';let ac={};for(let j of state.journals.filter(j=>inPeriod(j.date))){ac[j.account]??={Account:j.account,'Debit USD':0,'Credit USD':0};ac[j.account]['Debit USD']+=j.debit/100;ac[j.account]['Credit USD']+=j.credit/100}data=Object.values(ac).map(a=>({...a,'Debit USD':a['Debit USD'].toFixed(2),'Credit USD':a['Credit USD'].toFixed(2)}));let debit=state.journals.filter(j=>inPeriod(j.date)).reduce((s,j)=>s+j.debit,0),credit=state.journals.filter(j=>inPeriod(j.date)).reduce((s,j)=>s+j.credit,0);data.push({Account:'TOTAL','Debit USD':(debit/100).toFixed(2),'Credit USD':(credit/100).toFixed(2)})}if(kind==='audit'){title='Audit trail';data=state.audit.filter(a=>inPeriod(a.date)).sort((a,b)=>b.date.localeCompare(a.date)).map(a=>({Date:a.date,User:a.user_id,Action:a.action,Source:a.source_id,Detail:a.detail}))}modal(title,`<article class="receipt"><img class="print-logo" src="/brand-logo-current.png" alt="Thachi Investiments logo"><h1>${esc(state.settings.business.name)}</h1><h2>${title}</h2><p>${fullDate(today())} · ${data.length} rows</p><div class="table-scroll"><table><thead><tr>${Object.keys(data[0]||{}).map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${data.map(d=>`<tr>${Object.values(d).map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')||'<tr><td class="empty">No matching records</td></tr>'}</tbody></table></div></article><div class="print-actions"><button id="report-print">Print / save PDF</button><button class="primary" id="report-csv">Export CSV</button></div>`,true);$('#report-print').onclick=()=>window.print();$('#report-csv').onclick=()=>csvDownload(kind,data)}
function syncModal(){modal('Synchronization centre',`<div class="form-note">Terminal <strong>${esc(device)}</strong> · ${navigator.onLine?'Online':'Offline'}<br>Last success: ${lastSync?new Date(lastSync).toLocaleString():'Never'}<br>Pending records survive browser restart. Conflicting records never post partially.</div><div class="section-gap">${queue.slice().reverse().map(q=>`<div class="sync-item"><div class="row"><strong class="grow">${esc(q.kind)} · ${shortDate(q.event_time)}</strong>${badge(q.status,q.status==='conflict'?'red':q.status==='synced'?'':'amber')}</div><p class="muted">${esc(q.id)}</p>${q.error?`<p class="error">${esc(q.error)}</p>`:''}${q.status==='conflict'?`<div class="row"><button class="small" data-conflict="${q.id}">Review original payload</button><button class="small danger" data-abandon="${q.id}">Mark rejected after review</button></div>`:''}</div>`).join('')||'<div class="empty">All caught up. No queued transactions.</div>'}</div><div class="form-actions"><button class="primary" id="retry-sync">${icon('sync')} Sync / retry now</button></div>`);$('#retry-sync').onclick=async()=>{await sync();syncModal()};$$('[data-conflict]').forEach(b=>b.onclick=()=>{let q=queue.find(q=>q.id===b.dataset.conflict);modal('Conflict evidence',`<p class="muted">No stock or accounting entries were posted for this event. Review physical stock and the provisional receipt. A manager may reject it, then record a corrected sale as a new transaction.</p><pre style="white-space:pre-wrap;font-size:11px">${esc(JSON.stringify(q,null,2))}</pre><button id="back-sync">Back to synchronization</button>`);$('#back-sync').onclick=syncModal});$$('[data-abandon]').forEach(b=>b.onclick=()=>{if(!['super_admin','admin','manager'].includes(state.user.role))return toast('Manager review required',true);form('Reject conflicted transaction',input('reason','Reconciliation reason','','text','required minlength="8"'),'draft',x=>x);const formEl=$('#entry-form');formEl.onsubmit=async e=>{e.preventDefault();if(!await ask({title:'Reject this offline transaction?',message:'It will not be synchronized. Its original details and your reconciliation reason will be retained as evidence.',confirmLabel:'Reject transaction'}))return;const q=queue.find(q=>q.id===b.dataset.abandon);q.status='abandoned';q.resolution={user:state.user.id,date:new Date().toISOString(),reason:new FormData(e.target).get('reason')};await put('queue',queue);download('conflict-'+q.id+'.json',new Blob([JSON.stringify(q,null,2)],{type:'application/json'}));syncModal();render()}})}
function openRegistration(){
 if(!navigator.onLine)return toast('Account registration requires a connection.',true);
 modal('Create your account',`<form id="registration-form" class="stack"><p class="muted registration-intro">Join the Thachi pharmacy workspace. New accounts receive cashier access; your administrator manages additional permissions.</p>${input('name','Full name','','text','required minlength="2" maxlength="100" autocomplete="name"')}${input('email','Email address',$('#login-form [name=email]')?.value||'','email','required maxlength="254" autocomplete="username"')}${input('password','Password (12 characters minimum)','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}${input('confirm_password','Confirm password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<button type="button" class="registration-password-toggle" id="registration-toggle">${icon('eye')} Show passwords</button><div id="registration-error" class="error" role="alert"></div><div class="form-actions"><button id="registration-cancel" type="button">Cancel</button><button class="primary" type="submit">${icon('user')} Create account</button></div><p class="muted registration-signin">Already registered? <button type="button" id="registration-signin">Back to sign in</button></p></form>`);
 $('#registration-cancel').onclick=()=>$('#modal').close();$('#registration-signin').onclick=()=>$('#modal').close();
 $('#registration-toggle').onclick=()=>{const inputs=$$('#registration-form input[type=password],#registration-form input[data-password]'),show=inputs.some(i=>i.type==='password');inputs.forEach(i=>{i.dataset.password='true';i.type=show?'text':'password'});$('#registration-toggle').innerHTML=icon(show?'eye-off':'eye')+(show?' Hide passwords':' Show passwords')};
 $('#registration-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter||e.target.querySelector('button[type=submit]');button.disabled=true;$('#registration-error').textContent='';try{const data=Object.fromEntries(new FormData(e.target));if(data.password!==data.confirm_password)throw Error('Passwords do not match.');const result=await api('register',data);$('#modal').close();$('#login-form [name=email]').value=result.user.email;$('#login-password').value='';$('#login-password').focus();toast(result.message)}catch(error){$('#registration-error').textContent=error instanceof TypeError?'Connection interrupted. Try signing in with these credentials before retrying registration.':error.message}finally{button.disabled=false}};
}
function login(){ $('#app').innerHTML=`<div class="login reference-login"><section class="login-art"><div class="brand company-brand"><span class="brand-image"><img src="/brand-logo-current.png" alt="Thachi Investments logo"><img class="brand-pill-accent" src="/brand-logo-current.png" alt="" aria-hidden="true"></span></div><div class="login-message"><h1>Better care<br><span>starts here.</span></h1><p>Manage your pharmacy<br>with confidence.</p></div><div class="login-illustration" aria-hidden="true"><span class="login-orb orb-one"></span><span class="login-orb orb-two"></span><span class="login-orb orb-three"></span><span class="glass-pill"><i></i></span><span class="pill-orbit orbit-one"></span><span class="pill-orbit orbit-two"></span></div><div class="login-art-footer"><span></span>Inventory <b>&bull;</b> Billing <b>&bull;</b> Cash flow</div></section><section class="login-panel"><form id="login-form"><div class="login-mobile-brand"><img src="/brand-logo-current.png" alt="Thachi Investments logo"></div><div class="login-welcome"><h1>Welcome back</h1><p>Sign in to your pharmacy workspace</p></div>${loginNotice?`<p class="login-idle-note" role="status">${esc(loginNotice)}</p>`:''}<div class="login-fields"><label>Email address<div class="login-input-wrap">${icon('mail')}<input name="email" type="email" placeholder="you@company.com" value="${esc(localStorage.getItem('login-email')||'')}" required autocomplete="username"></div></label><label>Password<div class="login-input-wrap">${icon('lock')}<input name="password" id="login-password" type="password" placeholder="Enter your password" required autocomplete="current-password"><button id="toggle-password" type="button" aria-label="Show password" aria-pressed="false">${icon('eye')}</button></div></label></div><div class="login-options"><label class="remember-option" title="Remember your email; your password is still required after closing the browser."><input type="checkbox" name="remember" ${localStorage.getItem('login-email')?'checked':''}>Remember me</label><button class="login-help-link" id="forgot-password" type="button">Forgot password?</button></div><button class="primary login-submit" type="submit" ${lockingSession?'disabled':''}>Sign in ${icon('arrow')}</button><div id="login-error" class="error" role="alert"></div><div class="login-access">New here? <button type="button" id="open-registration">Create an account</button><span class="login-access-secondary">Need help? <button type="button" id="contact-admin">Contact your administrator</button></span></div><div class="login-secure">${icon('lock')}Secure pharmacy management &middot; 5-minute inactivity logout</div></form></section></div>`;
$('#open-registration').onclick=openRegistration;
$('#toggle-password').onclick=()=>{const field=$('#login-password'),show=field.type==='password';field.type=show?'text':'password';$('#toggle-password').innerHTML=icon(show?'eye-off':'eye');$('#toggle-password').setAttribute('aria-label',show?'Hide password':'Show password');$('#toggle-password').setAttribute('aria-pressed',String(show))};
const accessHelp=()=>modal('Account access & password recovery',`<div class="stack"><p>Your pharmacy administrator manages account access and password resets. Contact your branch manager to request a reset or a new account.</p><div class="form-note">${$('#login-form [name=email]').value?'Account: <strong>'+esc($('#login-form [name=email]').value)+'</strong><br>':''}For your security, passwords cannot be recovered or displayed. After a reset, reconnect this device and sign in with your new password.</div><p class="muted">Keep any pending offline transactions on the original device so your administrator can help reconcile them before clearing its local workspace.</p><button class="primary" id="close-access-help">Back to sign in</button></div>`);
$('#forgot-password').onclick=()=>{accessHelp();$('#close-access-help').onclick=()=>$('#modal').close()};$('#contact-admin').onclick=()=>{accessHelp();$('#close-access-help').onclick=()=>$('#modal').close()};

;$('#login-form').onsubmit=async e=>{e.preventDefault();if(lockingSession){toast('Finishing sign-out. Please try again in a moment.');return}let b=e.submitter||e.target.querySelector('button.primary');b.disabled=true;try{const credentials=Object.fromEntries(new FormData(e.target));if(credentials.remember)localStorage.setItem('login-email',credentials.email);else localStorage.removeItem('login-email');delete credentials.remember;let r;try{r=await api('login',credentials)}catch(err){if(!(err instanceof TypeError))throw err;await unlockVault(credentials.email,credentials.password);let cached=await get('state');if(cached?.production||cached?.settings?.policy?.offlineEnabled===false)throw Error('Production sign-in requires a connection.');if(!cached||Date.now()-Date.parse(cached.server_time)>cached.settings.policy.offlineHours*3600000)throw Error('Offline authorization expired. Connect and sign in.');token=await get('token');state=cached;queue=await get('queue')||[];lastSync=await get('lastSync')||'';beginSession();render();toast('Offline workspace unlocked');return}await unlockVault(credentials.email,credentials.password);queue=await get('queue')||[];state=r.state;token=state.production?'cookie-auth':r.token;lastSync=state.server_time;if(state.production){localStorage.setItem('auth-mode','cookie');sessionStorage.removeItem('token');await put('token',null)}else{localStorage.removeItem('auth-mode');sessionStorage.setItem('token',token);await put('token',token)}await put('state',state);await put('lastSync',lastSync);beginSession();render();sync()}catch(err){$('#login-error').textContent=err.message}finally{b.disabled=false}}}
window.addEventListener('hashchange',()=>{const raw=location.hash.slice(1)||'dashboard',invoiceRoute=raw.match(/^sales\/invoice\/([A-Za-z0-9-]+)$/);if(invoiceRoute){selectedInvoiceId=invoiceRoute[1];route='sales';subtab='detail';search='';render();return}const r=raw;if(r!==route||(subtab==='detail'&&r==='sales')){route=r;subtab='';search='';render()}});window.addEventListener('online',()=>{if(state){render();sync()}});window.addEventListener('offline',()=>{if(state)render()});
async function start(){await ready;const savedKey=sessionStorage.getItem('vault-key');if(!savedKey){token=null;render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});return}vaultKey=await crypto.subtle.importKey('raw',new Uint8Array(JSON.parse(savedKey)),{name:'AES-GCM'},true,['encrypt','decrypt']);queue=(await get('queue'))||[];queue.forEach(q=>{if(q.status==='syncing')q.status='pending'});token=token||await get('token')||(localStorage.getItem('auth-mode')==='cookie'?'cookie-auth':null);lastSync=await get('lastSync')||'';if(token){try{state=await api('state');await put('state',state);lastSync=state.server_time}catch(e){if(e instanceof TypeError){state=await get('state');if(state?.production){state=null;toast('Production sign-in requires a live connection.',true)}else if(state&&Date.now()-Date.parse(state.server_time)>state.settings.policy.offlineHours*3600000){state=null;toast('Offline access expired. Reconnect to sign in.',true)}}else{await automaticLogout(e.message)}}}if(state)beginSession(true);render();if(state)sync();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{})}
setInterval(()=>{if(state&&navigator.onLine){activityHeartbeat();if(pending())sync()}},30000);
start().catch(e=>{$('#app').innerHTML=`<div class="empty"><h1>Storage unavailable</h1><p>${esc(e.message)}</p><p>Use a regular browser window with local storage enabled.</p></div>`});
